window.DIGEST_ARCHIVE=window.DIGEST_ARCHIVE||{};window.DIGEST_ARCHIVE["2026-08-21"]={"date": "2026-08-21", "dateKR": "2026년 8월 21일", "dateEN": "21 August 2026", "total": 123, "sections": [{"code": "TOP", "type": "news", "kTitle": "Section 1. 주요 뉴스", "eTitle": "Section 1. Top News", "items": [{"code": "TOP", "title": "Panama Canal begins reducing daily transits amid worsening drought", "src": "maritime-executive", "date": "2026-08-20", "kSum": "파나마 운하청(ACP)이 가뭄 악화 전망에 따라 통항 제한을 확대했다. 기존에는 선박 최대 흘수(draft) 제한에 초점을 맞췄으나, 이번에는 하루 통항 척수(daily transits) 자체를 줄이는 쪽으로 전환했다. 올해 수문연도 기준 누적 강우량이 34% 감소하고 유역 유입량이 44% 감소한 데 따른 조치다.", "eSum": "The Panama Canal Authority (ACP) has expanded transit restrictions as forecasts for a worsening drought grow. Having previously focused on maximum vessel draft, it is now shifting to reducing the number of daily transits, responding to a 34% drop in accumulated rainfall and a 44% fall in water inflows to the watershed this hydrological year.", "kImp": "파나마 운하는 미주-아시아 및 대서양-태평양 물동량의 핵심 관문으로, 통항 척수 축소는 컨테이너·LPG·자동차운반선 등 정기선 스케줄과 운임에 직접적 영향을 준다. 기후 리스크가 구조적 공급망 병목으로 재부상하고 있음을 보여준다.", "eImp": "As a critical artery for Americas-Asia and Atlantic-Pacific trade, cuts to daily slots directly hit liner schedules and rates across containers, LPG and car carriers, underscoring how climate risk is re-emerging as a structural supply-chain bottleneck.", "url": "https://maritime-executive.com/article/panama-canal-begins-reducing-daily-transits-due-to-declining-water-levels"}, {"code": "TOP", "title": "Navios Partners takes VLCC newbuild spend past $840m with fresh trio", "src": "splash247", "date": "2026-08-20", "kSum": "뉴욕 상장사 나비오스 마리타임 파트너스(Navios Maritime Partners)가 스크러버 장착 VLCC 신조선 3척을 3억6,150만 달러에 추가 발주했다. 이로써 안젤리키 프란구(Angeliki Frangou)가 이끄는 이 선사의 신규 초대형 원유운반선 프로그램은 총 7척, 8억4,350만 달러 규모로 확대됐다. 이번 3척은 6~7월에 척당 1억2,050만 달러 수준에 계약됐다.", "eSum": "New York-listed Navios Maritime Partners has ordered three more scrubber-fitted VLCC newbuildings in a $361.5m deal, taking its fresh supertanker programme to seven ships worth $843.5m. The Angeliki Frangou-led owner agreed the latest trio in June and July at about $120.5m each.", "kImp": "대형 그리스계 선주의 공격적 VLCC 신조 투자는 원유 톤마일 수요와 노후선 교체에 대한 강세 전망을 반영한다. 지정학적 불안 속 탱커 시황 호조가 신조 발주로 이어지는 흐름을 보여준다.", "eImp": "Aggressive VLCC ordering by a major Greek owner signals bullish bets on crude tonne-mile demand and fleet renewal, illustrating how firm tanker earnings amid geopolitical disruption are feeding into a newbuilding wave.", "url": "https://splash247.com/navios-partners-takes-vlcc-newbuild-spend-past-840m-with-fresh-trio/"}, {"code": "TOP", "title": "Japan to construct first large shipbuilding dock since 2017", "src": "splash247", "date": "2026-08-20", "kSum": "일본이 2017년 이후 처음으로 대형 신조 도크를 건설한다. 나무라조선(Namura Shipbuilding) 등이 관련된 것으로 알려졌으며, 이는 근 10년 만의 일본 대형 건조 능력 확충 움직임이다.", "eSum": "Japan is set to build its first large shipbuilding dock in nearly a decade, its first since 2017, in a move to expand large newbuilding capacity as the country seeks to reinforce its shipbuilding base.", "kImp": "중국·한국이 주도하는 세계 신조 시장에서 일본이 대형 도크 신설로 건조 능력 회복에 나선 것은 조선 3국 경쟁 구도와 향후 선복 공급에 의미 있는 신호다.", "eImp": "With China and Korea dominating newbuilding, Japan's move to add large-dock capacity is a notable signal for the three-way shipbuilding rivalry and future tonnage supply.", "url": "https://splash247.com/japan-to-construct-first-large-shipbuilding-dock-since-2017/"}, {"code": "TOP", "title": "Seoul probes safety conditions at HD Hyundai following subcontractor deaths", "src": "splash247", "date": "2026-08-19", "kSum": "한국 정부가 사내 협력업체 근로자 사망 사고가 잇따르자 HD현대중공업(HD Hyundai Heavy)에 대한 전면적인 안전 조사에 착수했다. 조선소 작업 안전 관리 실태 전반이 조사 대상이다.", "eSum": "South Korea has launched a sweeping safety investigation into HD Hyundai Heavy Industries following a series of subcontractor deaths, scrutinising safety management across the shipyard's operations.", "kImp": "세계 최대급 조선소의 산업안전 문제는 수주 호황 속 인력·안전 관리 부담을 드러낸다. 규제 강화와 작업 중단 리스크는 인도 일정과 발주처 신뢰에 영향을 줄 수 있다.", "eImp": "Safety failures at one of the world's largest shipbuilders expose the strain of labour and safety management amid an order boom; tighter regulation and possible work stoppages could affect delivery schedules and buyer confidence.", "url": "https://splash247.com/seoul-probes-safety-conditions-at-hd-hyundai-following-subcontractor-deaths/"}, {"code": "TOP", "title": "CK Hutchison piles another $1.5bn claim onto Panama ports battle", "src": "splash247", "date": "2026-08-20", "kSum": "CK 허치슨(CK Hutchison)이 파나마 항만 사업권을 둘러싼 분쟁에서 15억 달러 규모의 추가 청구를 제기했다. 발보아·크리스토발 터미널 등 파나마 항만 자산 매각을 둘러싼 법적 공방이 격화되고 있다.", "eSum": "CK Hutchison has added another $1.5bn claim to the ongoing battle over its Panama port concessions, escalating the legal dispute surrounding the sale of Panama terminal assets including Balboa and Cristobal.", "kImp": "파나마 운하 양단 핵심 컨테이너 터미널의 소유권 분쟁은 지정학·통상 갈등과 맞물려 글로벌 항만 네트워크 재편의 향방을 가른다. 미-중 긴장 속 전략 인프라 통제권 문제가 부각된다.", "eImp": "The ownership fight over key container terminals at both ends of the Panama Canal, entangled with geopolitics and trade tensions, will shape the reshuffling of global port networks and highlights control of strategic infrastructure amid US-China friction.", "url": "https://splash247.com/ck-hutchison-piles-another-1-5bn-claim-onto-panama-ports-battle/"}, {"code": "TOP", "title": "Finland taps domestic yard for new icebreaker", "src": "splash247", "date": "2026-08-20", "kSum": "헬싱키조선소(Helsinki Shipyard)가 핀란드의 차세대 쇄빙선 건조 계약을 따냈다. 신조 쇄빙선은 1954년 건조된 노후 쇄빙선을 대체하게 된다.", "eSum": "Helsinki Shipyard has won the contract to build Finland's next icebreaker, with the new vessel set to replace a 1954-built ship in the national icebreaker fleet.", "kImp": "북극·발트해 항로의 겨울철 통항 유지를 위한 쇄빙선 확충은 극지 물류와 안보 측면에서 중요하다. 자국 조선소 활용은 유럽의 전략 조선 역량 유지 의지를 보여준다.", "eImp": "Renewing icebreaker capacity is vital for keeping Arctic and Baltic routes open in winter, with implications for polar logistics and security; awarding a domestic yard signals Europe's intent to preserve strategic shipbuilding capability.", "url": "https://splash247.com/finland-taps-domestic-yard-for-new-icebreaker/"}, {"code": "TOP", "title": "Hudong-Zhonghua details expansion plans", "src": "splash247", "date": "2026-08-20", "kSum": "중국 후둥중화조선(Hudong-Zhonghua Shipbuilding)이 또 한 차례 대규모 설비 확장 계획을 구체화했다. LNG선 등 고부가 선박 건조 능력 확대를 겨냥한 것으로 보인다.", "eSum": "China's Hudong-Zhonghua Shipbuilding is pushing ahead with another major expansion of its facilities, aimed at growing capacity for high-value tonnage such as LNG carriers.", "kImp": "중국 대표 조선소의 지속적 증설은 LNG선을 포함한 글로벌 신조 공급 능력 확대와 한·중 경쟁 심화를 의미한다. 향후 선가와 인도 슬롯 확보에 영향을 준다.", "eImp": "Continued expansion by a flagship Chinese yard means growing global newbuilding capacity, including LNG carriers, and intensifying Korea-China competition, with knock-on effects for prices and delivery-slot availability.", "url": "https://splash247.com/hudong-zhonghua-details-expansion-plans/"}, {"code": "TOP", "title": "Centrofin moves into boxships with Hengli pair", "src": "splash247", "date": "2026-08-20", "kSum": "그리스 선주 센트로핀 매니지먼트(Centrofin Management)가 첫 컨테이너선 신조로 중국 헝리중공업(Hengli)에 2척을 발주한 것으로 전해졌다. 기존 탱커 중심 선대에서 컨테이너 부문으로 사업을 확장하는 행보다.", "eSum": "Greek owner Centrofin Management has been linked to its first containership newbuildings, ordering a pair at China's Hengli, marking a move beyond its traditional tanker-focused fleet into the container segment.", "kImp": "전통적 탱커 선주의 컨테이너선 진출은 선주들의 포트폴리오 다변화와 중국 신흥 조선소로의 발주 확산 흐름을 보여준다.", "eImp": "A traditional tanker owner's entry into containerships illustrates owner portfolio diversification and the spread of orders to emerging Chinese yards.", "url": "https://splash247.com/centrofin-moves-into-boxships-with-hengli-pair/"}, {"code": "TOP", "title": "Car carriers step up push for more accurate emissions data", "src": "splash247", "date": "2026-08-19", "kSum": "주요 글로벌 자동차운반선(PCTC) 선사들의 연합체가 배출량 데이터의 정확성을 높이기 위한 노력을 강화하고 있다. 실측 기반의 신뢰도 높은 배출 데이터 확보를 목표로 한다.", "eSum": "A coalition of major global car carrier operators is stepping up efforts to obtain more accurate emissions data, aiming for reliable, measurement-based reporting across the vehicle-carrier sector.", "kImp": "정확한 배출 데이터는 IMO·EU ETS 등 규제 대응과 화주 요구 충족의 기반이다. PCTC 선사들의 공동 대응은 탈탄소 규제 강화에 대한 업계의 준비를 반영한다.", "eImp": "Accurate emissions data underpins compliance with IMO and EU ETS rules and shipper demands; a joint push by car carriers reflects the sector's preparation for tightening decarbonisation regulation.", "url": "https://splash247.com/car-carriers-step-up-push-for-more-accurate-emissions-data/"}, {"code": "TOP", "title": "NBOSCO seals four-ship boxship deal with Wuchang", "src": "splash247", "date": "2026-08-19", "kSum": "닝보오션시핑(NBOSCO, Ningbo Ocean Shipping)이 우창조선(Wuchang)과 피더 컨테이너선 4척 신조 프로그램을 확정했다. 지역 피더 선대 확충을 위한 발주다.", "eSum": "Ningbo Ocean Shipping (NBOSCO) has firmed up a four-ship feeder containership newbuilding programme with Wuchang, expanding its regional feeder fleet.", "kImp": "중국 선사들의 피더선 발주 확대는 역내 물류 네트워크 강화와 컨테이너 신조 수요 지속을 보여준다. 중소형 컨테이너선 시장의 활황을 시사한다.", "eImp": "Expanding feeder orders by Chinese carriers point to strengthening intra-regional logistics networks and sustained containership newbuilding demand, signalling a buoyant small-to-mid-size boxship market.", "url": "https://splash247.com/nbosco-seals-four-ship-boxship-deal-with-wuchang/"}]}, {"code": "ACC", "type": "accident", "kTitle": "Section 2. 해양사고", "eTitle": "Section 2. Accidents", "items": [{"code": "ACC", "title": "Sanctioned product tanker Seamull hijacked in Gulf of Aden", "src": "seatrade-maritime", "date": "2026-08-20", "kSum": "예멘 알무칼라(Al Mukalla) 동쪽 약 136해리 아덴만에서 제품운반선 시멀(Seamull, 별칭 Sibu 1, 2001년 건조, 32,000dwt)이 피랍됐다. 선박이 VHF 16번으로 조난신호를 보낸 뒤 무장 6인이 승선해 선박을 장악하고 소말리아 방향으로 침로를 변경했다고 UKMTO가 밝혔다. 선원 상태는 확인되지 않았다. 해당 선박은 이란산 석유제품 운송으로 2025년 12월 미 OFAC 제재를 받았고, 에리트레아 기(旗)로 허위 등록된 상태였다.", "eSum": "The 2001-built, 32,000 dwt product tanker Seamull (aka Sibu 1) was hijacked about 136 nm east of Al Mukalla, Yemen, in the Gulf of Aden. Per UKMTO, the ship sent a VHF16 distress call before six armed persons boarded, took control and redirected it toward Somalia; crew status was unknown. The vessel, falsely flagged in Eritrea, had been OFAC-sanctioned in December 2025 for carrying Iranian petroleum products.", "kCause": "무장 해적/피랍(선박 강제 승선 및 탈취). 배경으로 아덴만·소말리아 해역의 해적 위협 재고조가 지목된다.", "eCause": "Armed hijacking/piracy — forced boarding and seizure, against a backdrop of resurging piracy in the Gulf of Aden and off Somalia.", "kLes": "고위험 해역 통항 시 BMP(최선의 관리관행) 강화, 선체 보안조치, UKMTO/JMIC 보고 및 호송·경계 강화가 필요하다. 제재·섀도우플릿 선박은 지원·보호가 취약해 표적이 되기 쉽다.", "eLes": "In high-risk waters, reinforce BMP hardening, reporting to UKMTO/JMIC and escort/vigilance; sanctioned and shadow-fleet vessels lacking recognised support are especially vulnerable targets.", "url": "https://www.seatrade-maritime.com/security/sanctioned-tanker-hijacked-in-gulf-of-aden"}, {"code": "ACC", "title": "General cargo ship Lutuf hijacked off Somalia", "src": "gcaptain", "date": "2026-08-17", "kSum": "소말리아 마레요(Mareeyo) 남쪽 약 4해리 해상에서 1,401dwt 일반화물선 루투프(Lutuf)가 피랍됐다. 무장 8인이 승선해 선박을 장악했으며, 월요일 1136 UTC에 선사 보안책임자가 신고했다고 UKMTO가 전했다. 남서 몬순으로 원해 활동이 제약되는 시기임에도 연안 은신 해역에서 해적 활동이 이어지고 있다. JMIC에 따르면 이 지역에서는 이미 여러 척이 억류 중이다.", "eSum": "The 1,401 dwt general cargo ship Lutuf was hijacked about 4 nm south of Mareeyo, Somalia. UKMTO said eight armed persons boarded and seized control, reported by the ship's company security officer at 1136 UTC Monday. Despite southwest monsoon conditions limiting offshore operations, piracy persists in sheltered coastal waters, with several vessels already held in the region per JMIC.", "kCause": "무장 해적에 의한 피랍(연안 은신 해역에서의 승선·탈취).", "eCause": "Armed piracy — boarding and seizure exploiting sheltered coastal waters.", "kLes": "몬순기에도 소말리아 연안 해역의 해적 위협은 상존한다. 연안 근접 통항 회피, 경계 강화, 신속 보고 및 은신처(citadel) 절차 점검이 요구된다.", "eLes": "Even during monsoon season the Somali coastal piracy threat remains; avoid close-coastal transits, heighten vigilance, report promptly and review citadel procedures.", "url": "https://gcaptain.com/armed-pirates-hijack-cargo-ship-off-somalia/"}, {"code": "ACC", "title": "Bulk carrier Anna S burned out by five drone strikes in Black Sea", "src": "seatrade-maritime", "date": "2026-08-19", "kSum": "라이베리아 선적 벌크선 안나 S(Anna S)가 8월 17일 노보로시스크 인근 약 20해리 해상에서 공중 드론 5기에 피격돼 화재와 심각한 손상을 입었으며 현지 보도상 '완전 소실'됐다. 21명 전원이 퇴선해 인근 몰타 선적 벌크선 엘리나 B(Elina B)에 구조됐으나, 엘리나 B도 약 5시간 뒤 드론 2기에 피격됐다(항해 가능 상태 유지). 안나 S는 곡물 선적을 위해 노보로시스크로 향하던 중이었다.", "eSum": "Liberia-flagged bulk carrier Anna S was hit by five aerial drones on 17 August about 20 nm off Novorossiysk, causing a fire and major damage and reportedly leaving it 'completely burned out'. All 21 crew abandoned ship and were rescued by the Malta-flagged bulker Elina B, which was itself struck by two drones about five hours later but remained operational. Anna S was en route to load grain.", "kCause": "러시아-우크라이나 흑해 분쟁에 따른 드론 공격. 상선이 군수 물자 운송 의혹 등으로 표적이 됐다(공격 주체 관련 세부는 추정).", "eCause": "Drone attack amid the Russia-Ukraine Black Sea conflict; merchant vessels targeted in the tit-for-tat campaign (attribution details presumed/unconfirmed).", "kLes": "흑해·아조프해 통항 상선과 선원에 대한 위협이 급증하고 있다. 위험 구역 회피 라우팅, 정박·대기 위치 재검토, 실시간 위협정보 반영과 신속 퇴선·구조 대비가 필요하다. 곡물 수출입 공급망 리스크도 확대된다.", "eLes": "Threats to merchant ships and seafarers in the Black Sea and Sea of Azov are escalating; adopt risk-avoiding routing, review anchoring/waiting positions, act on real-time threat intelligence and prepare for rapid abandonment/rescue, while grain supply-chain risk widens.", "url": "https://www.seatrade-maritime.com/security/bulker-pounded-by-five-drone-strikes-in-black-sea"}, {"code": "ACC", "title": "Dry bulk carrier Minoan Pioneer struck off Oman, seafarer missing and oil leaking", "src": "gcaptain", "date": "2026-08-14", "kSum": "라이베리아 선적 벌크선 미노안 파이오니어(Minoan Pioneer)가 8월 3일 호르무즈 해협 통항 중 오만 연안 인근에서 정체불명의 발사체에 피격돼 선원 1명이 실종됐다고 해상보안 소식통이 전했다. 이 선박에서 유출된 기름이 이란 케슘섬(Qeshm Island) 인근에 약 160km에 이르는 슬릭을 형성한 것으로 분석됐다. 예인선이 좌초·손상 선박에 접근하려 했으나 이란 당국의 허가 문제로 접근하지 못했다.", "eSum": "The Liberia-flagged dry bulk carrier Minoan Pioneer was hit by an unknown projectile near Oman's coast while transiting the Strait of Hormuz on 3 August, leaving one seafarer missing, maritime security sources said. Oil leaking from the vessel is assessed to have formed a slick stretching some 160 km off Iran's Qeshm Island. A tug dispatched to secure the stricken ship could not approach due to permission issues with Iranian authorities.", "kCause": "이란의 공격으로 추정되는 발사체 피격(로이터도 원인을 독립 확인하지 못함, 추정). 이후 선체 손상으로 인한 기름 유출.", "eCause": "Presumed Iranian projectile strike (Reuters could not independently confirm — presumed), with subsequent oil leakage from hull damage.", "kLes": "호르무즈 해협 등 분쟁 인접 해역 통항 리스크가 극도로 높다. 지정학적 접근 제약으로 구조·오염방제·인양이 지연될 수 있어 사전 위기대응·통항 판단과 P&I·보험 커버 점검이 중요하다.", "eLes": "Transit risk in conflict-adjacent waters such as Hormuz is extreme; geopolitical access constraints can delay rescue, pollution response and salvage, making pre-planned crisis response, routing decisions and insurance/P&I cover review essential.", "url": "https://gcaptain.com/two-slicks-appear-in-gulf-as-huge-oil-spill-off-oman-threatens-disaster/"}, {"code": "ACC", "title": "BSU investigation: toxic gas release from chemical mix-up aboard LNG tanker", "src": "safety4sea", "date": "2026-08-18", "kSum": "독일 연방해양사고조사국(BSU)이 LNG 탱커에서 발생한 화학물질 관련 직무 사고 조사보고서를 발표했다. 2024년 8월 5일 트라베뮌데(Travemünde) 항에서 기관부 조기수(motorman)가 오수처리장치(STP)의 차아염소산나트륨(NaOCl) 정량 탱크를 보충하려다, 화학품 창고에서 실수로 38~40% 아황산수소나트륨(NaHSO3) 용액을 가져와 주입했다. 잔류 NaOCl과 혼합되며 발열반응이 일어나 유독가스가 방출되고 플라스틱 정량 탱크가 파열됐다.", "eSum": "Germany's Federal Bureau of Maritime Casualty Investigation (BSU) published a report into an occupational chemical accident aboard an LNG tanker. On 5 August 2024 at Travemünde, a motorman refilling the sewage treatment plant's sodium hypochlorite (NaOCl) dosing tank inadvertently took a 38-40% sodium bisulphite (NaHSO3) solution from the chemical store; mixing with residual NaOCl triggered an exothermic reaction that released toxic gases and ruptured the plastic dosing tank.", "kCause": "동일 외형 용기에서 잘못된 화학물질(아황산수소나트륨)을 취해 주입한 인적 오류. 배경 요인으로 STP 설계·설치, 화학품 라벨·보관·안전정보 및 위험관리 미흡이 지적됐다.", "eCause": "Human error in taking and pouring the wrong chemical (sodium bisulphite); contributing factors identified include STP design/installation and gaps in chemical labelling, storage, safety information and risk management.", "kLes": "선상 화학품의 명확한 표시·격리 보관, 물질안전보건자료(MSDS) 숙지, 정량주입 작업 절차·이중확인, STP 설계 및 위험성평가 개선이 요구된다.", "eLes": "Ensure clear labelling and segregated storage of shipboard chemicals, MSDS awareness, procedures and double-checks for dosing tasks, and improved STP design and risk assessment.", "url": "https://safety4sea.com/bsu-investigation-occupational-accident-involving-chemicals-aboard-lng-tanker/"}]}, {"code": "PSC", "type": "news", "kTitle": "Section 3. 항만국통제", "eTitle": "Section 3. Port State Control", "items": [{"code": "PSC", "title": "Cargo securing on the PSC agenda", "src": "gard.no", "date": "2026-08-14", "kSum": "가드(Gard)는 파리 및 도쿄 MOU가 2026년 9월 1일부터 11월 30일까지 화물 고박(cargo securing)을 주제로 한 집중점검 캠페인(CIC)을 실시한다고 안내했다. 점검 초점은 선박별로 승인된 화물고박매뉴얼(CSM) 비치 여부, 승무원의 매뉴얼 숙지도, VGM을 반영한 적재계획, 고박장비의 상태 및 유지관리다. 파리·도쿄 MOU의 공동 보도자료와 공식 질문지는 8월 3일 공개됐다. 가드는 화물 고박 미비가 화물 유실, 복원성 저하, 선원 안전 위험으로 이어질 수 있어 단순 규정 준수 문제를 넘어선다고 강조했다.", "eSum": "Gard advises that the Paris and Tokyo MOUs will run a joint Concentrated Inspection Campaign (CIC) on cargo securing from 1 September to 30 November 2026. Inspection focus includes the carriage of an approved ship-specific Cargo Securing Manual (CSM), officers' familiarity with it, cargo plans reflecting verified gross mass (VGM), and the condition and maintenance of securing equipment. The MOUs' joint press release and questionnaire were published on 3 August. Gard stresses that poor cargo securing is more than a compliance issue, as it can lead to cargo loss, stability problems and crew safety risks.", "kImp": "9~11월 CIC 기간 중 CSM 미비나 고박장비 결함은 억류로 이어질 수 있으므로, 선사·선박은 매뉴얼 최신화, 장비 정비, 선원 교육을 사전에 점검해야 한다. 특히 컨테이너선·자동차운반선·브레이크벌크 등 다수 화물단위를 운송하는 선박의 준비가 중요하다.", "eImp": "During the September-November CIC, missing CSMs or defective securing gear can result in detention, so operators should verify manuals are current, equipment is maintained and crews are trained ahead of time. Preparation is especially critical for ships carrying multiple cargo units such as containers, vehicles and break-bulk.", "url": "https://gard.no/en/insights/cargo-securing-psc-agenda/"}, {"code": "PSC", "title": "Bulk Carrier Pacific Energy Detained at Abbot Point", "src": "trusteddocks", "date": "2026-08-20", "kSum": "홍콩 선적 벌크선 퍼시픽 에너지(Pacific Energy, IMO 9536430)가 2026년 7월 28일 호주 퀸즐랜드 애벗포인트(Abbot Point)에서 도쿄 MOU 항만국통제(PSC) 점검을 받고 억류됐다. 점검관은 총 13건의 결함을 적발했고, 그중 1건이 억류사유로 분류됐다. 선박(총톤수 52,735t)은 화양해사센터(Huayang Maritime Center)가 ISM 관리하고 있으며, 결함이 시정될 때까지 항내에 억류된다.", "eSum": "The Hong Kong-flagged bulk carrier Pacific Energy (IMO 9536430) was detained after a Tokyo MOU Port State Control inspection at Abbot Point, Queensland, on 28 July 2026. Inspectors recorded 13 deficiencies in total, one of which was classified as detainable. The 52,735 GT vessel, managed under the ISM Code by Huayang Maritime Center, will remain detained until the outstanding deficiency is rectified.", "kImp": "호주 AMSA는 위험기반 표적점검을 강화하고 있어, 단 1건의 억류사유 결함으로도 대형 벌크선이 주요 석탄 수출항에서 발이 묶일 수 있음을 보여준다. 벌크선 부문은 최근 PSC 압박이 지속되는 세그먼트로 각별한 사전 정비가 요구된다.", "eImp": "With AMSA intensifying risk-based targeting, the case shows that a single detainable deficiency can hold up a large bulker at a key coal export port. The bulk segment remains under continued PSC pressure, underlining the need for thorough pre-arrival maintenance.", "url": "https://www.trusteddocks.com/news/5942-bulk-carrier-pacific-energy-detained-at-abbot-point"}, {"code": "PSC", "title": "Container Ship Navios Azure Detained in Marsaxlokk", "src": "trusteddocks", "date": "2026-08-20", "kSum": "마셜제도 선적 컨테이너선 나비오스 아주르(Navios Azure, IMO 9324851)가 2026년 7월 31일 몰타 마르삭슬로크(Marsaxlokk)에서 파리 MOU PSC 점검을 받고 억류됐다. 점검관은 총 11건의 결함을 적발했고, 이 중 6건이 억류사유로 분류됐다. 선박(총톤수 39,906t)은 나비오스 컨테이너스 매니지먼트(Navios Containers Management)가 ISM 관리한다.", "eSum": "The Marshall Islands-flagged container ship Navios Azure (IMO 9324851) was detained after a Paris MOU Port State Control inspection at Marsaxlokk, Malta, on 31 July 2026. Inspectors identified 11 deficiencies, six of which were classified as detainable. The 39,906 GT vessel is managed under the ISM Code by Navios Containers Management and will stay in port until corrective actions are verified.", "kImp": "6건의 억류사유 결함은 심각한 안전관리 취약을 시사한다. 9월 화물고박 CIC를 앞두고 컨테이너선에 대한 파리 MOU의 점검 강도가 높아지는 흐름으로, 컨테이너 운영자의 선제적 대비가 필요하다.", "eImp": "Six detainable deficiencies point to serious safety-management weaknesses. Ahead of the September cargo-securing CIC, it signals intensifying Paris MOU scrutiny of container ships and the need for container operators to prepare proactively.", "url": "https://www.trusteddocks.com/news/5938-container-ship-navios-azure-detained-in-marsaxlokk"}, {"code": "PSC", "title": "Oil/Chemical Tanker DANIA J Detained in Constanta", "src": "trusteddocks", "date": "2026-08-20", "kSum": "코모로 선적 석유·화학 탱커 다니아 J(Dania J, IMO 9143893)가 2026년 7월 28일 루마니아 콘스탄차(Constanta)에서 흑해 MOU(Black Sea MOU) PSC 점검을 받고 억류됐다. 점검에서 무려 36건의 결함이 적발됐다. 개별 억류사유로 분류된 항목은 없었으나, 당국은 선박의 누적 상태가 억류를 정당화한다고 판단했다. 선박(총톤수 2,133t)은 다니아 마리타임(Dania Maritime Corp)이 ISM 관리한다.", "eSum": "The Comoros-flagged oil/chemical tanker Dania J (IMO 9143893) was detained after a Black Sea MOU Port State Control inspection at Constanta, Romania, on 28 July 2026. The inspection identified a total of 36 deficiencies. Although none were individually classified as detainable, authorities detained the vessel based on its cumulative condition. The 2,133 GT tanker is managed under the ISM Code by Dania Maritime Corp.", "kImp": "36건이라는 이례적으로 많은 결함은 편의치적 노후 탱커의 전반적 관리 부실을 드러낸다. 개별 억류사유가 없더라도 결함이 누적되면 억류될 수 있음을 보여주는 사례로, 흑해 지역의 substandard 선박에 대한 감시 강화 흐름을 반영한다.", "eImp": "An unusually high count of 36 deficiencies exposes systemic management failings on an ageing flag-of-convenience tanker. It shows that a cumulative burden of deficiencies can trigger detention even without an individually detainable item, reflecting tightening oversight of substandard ships in the Black Sea region.", "url": "https://www.trusteddocks.com/news/5941-oilchemical-tanker-dania-j-detained-in-constanta"}, {"code": "PSC", "title": "General Cargo Ship VULIN Detained at Port of Goole", "src": "trusteddocks", "date": "2026-08-20", "kSum": "코모로 선적 다목적 일반화물선 불린(Vulin, IMO 9015448)이 2026년 7월 30일 영국 구울(Goole)항에서 파리 MOU PSC 점검을 받고 억류됐다. 점검관은 총 17건의 결함을 적발했고, 그중 2건이 억류사유에 해당했다. 선박(총톤수 1,662t)은 웨스트 데니즈질리크(West Denizcilik Ticaret AS)가 ISM 관리한다.", "eSum": "The Comoros-flagged general cargo/multipurpose vessel Vulin (IMO 9015448) was detained after a Paris MOU Port State Control inspection at the Port of Goole, UK, on 30 July 2026. Inspectors identified 17 deficiencies, two of which were serious enough to warrant detention. The 1,662 GT vessel is managed under the ISM Code by West Denizcilik Ticaret AS.", "kImp": "17건의 다수 결함은 소형 노후 일반화물선의 정비·관리 취약을 보여준다. 영국 등 파리 MOU 항만에서 편의치적 소형선에 대한 점검이 촘촘하게 이뤄지고 있음을 시사한다.", "eImp": "The 17 deficiencies highlight maintenance and management weaknesses typical of small, ageing general cargo ships. It signals close Paris MOU scrutiny of small flag-of-convenience vessels at UK and European ports.", "url": "https://www.trusteddocks.com/news/5940-general-cargo-ship-vulin-detained-at-port-of-goole"}, {"code": "PSC", "title": "Bulk Carrier Lago Di Ledro Detained in Bordeaux", "src": "trusteddocks", "date": "2026-08-20", "kSum": "라이베리아 선적 벌크선 라고 디 레드로(Lago Di Ledro, IMO 9471654)가 2026년 7월 30일 프랑스 보르도(Bordeaux)에서 파리 MOU PSC 점검을 받고 억류됐다. 점검관은 총 10건의 결함을 적발했고, 그중 3건이 억류사유로 평가됐다. 선박(총톤수 24,150t)은 AGA 테크닉 데니즈질리크(AGA Teknik Denizcilik Sanayi)가 ISM 관리한다.", "eSum": "The Liberian-flagged bulk carrier Lago Di Ledro (IMO 9471654) was detained after a Paris MOU Port State Control inspection at Bordeaux, France, on 30 July 2026. Inspectors identified 10 deficiencies, three of which were assessed as detainable. The 24,150 GT vessel is managed under the ISM Code by AGA Teknik Denizcilik Sanayi.", "kImp": "3건의 억류사유 결함으로 중형 벌크선이 프랑스 항에서 억류된 사례로, 파리 MOU가 벌크선 부문에 대해 지속적인 점검 압박을 가하고 있음을 보여준다. 벌크선 운영자는 억류 위험을 줄이기 위한 상시 정비 체계가 필요하다.", "eImp": "With three detainable deficiencies grounding a mid-size bulker at a French port, the case reflects sustained Paris MOU pressure on the bulk segment. Bulk operators need robust ongoing maintenance regimes to reduce detention risk.", "url": "https://www.trusteddocks.com/news/5939-bulk-carrier-lago-di-ledro-detained-in-bordeaux"}, {"code": "PSC", "title": "Offshore Supply Vessel Britoil Power Detained in Constanta", "src": "trusteddocks", "date": "2026-08-20", "kSum": "룩셈부르크 선적 해양지원선(OSV) 브리토일 파워(Britoil Power, IMO 9384461)가 2026년 7월 21일 루마니아 콘스탄차(Constanta)에서 흑해 MOU PSC 점검을 받고 억류됐다. 점검에서 9건의 결함이 적발됐으며, 개별적으로 억류사유로 분류된 항목은 없었으나 당국은 선박을 억류했다. 선박(총톤수 2,615t)은 브리토일 오프쇼어 서비스(Britoil Offshore Services Srl)가 ISM 관리한다.", "eSum": "The Luxembourg-flagged offshore supply vessel Britoil Power (IMO 9384461) was detained after a Black Sea MOU Port State Control inspection at Constanta, Romania, on 21 July 2026. The inspection identified nine deficiencies; although none were individually classified as detainable, authorities still placed the vessel under detention. The 2,615 GT vessel is managed under the ISM Code by Britoil Offshore Services Srl.", "kImp": "해양지원선도 PSC 억류 대상에서 예외가 아니며, 개별 억류사유가 없어도 결함이 다수 누적되면 억류될 수 있음을 보여준다. 오프쇼어 선사도 상선과 동일한 수준의 PSC 대비가 필요하다.", "eImp": "Offshore support vessels are not exempt from PSC detention, and the case shows that an accumulation of deficiencies can lead to detention even without an individually detainable item. Offshore operators need PSC readiness on par with merchant ships.", "url": "https://www.trusteddocks.com/news/5944-offshore-supply-vessel-britoil-power-detained-in-constanta"}]}, {"code": "PCTC", "type": "news", "kTitle": "Section 4. 자동차운반선", "eTitle": "Section 4. PCTC / Car Carriers", "items": [{"code": "PCTC", "title": "2026년 PCTC 신조 발주 46척…중국 완성차 수출 붐이 견인", "src": "Shippax", "date": "2026-08-20", "kSum": "십팩스(Shippax)에 따르면 8월 15일 기준 2026년 들어 PCTC 신조가 46척 계약됐으며 대부분 2029년 인도 슬롯을 확보했다. 중국의 상반기 완성차 수출은 509만6천대(전년比 +65.5%)로 급증했고 6월 단월 수출은 103만7천대(+75%)를 기록했다. SFL은 CIMC 래플즈(CIMC Raffles)에 7,000CEU 이중연료선을 발주(BYD 로지스틱스 장기용선 추정)했고, 조디악(Zodiac)은 동일 조선소에 6척, EPS는 중국초상(China Merchants) 진링·웨이하이에 각 3척을 후속 발주했다. 7,000CEU 이중연료선 선가는 약 1억달러 수준으로 파악된다. 1군 중국 선사 대신 옌판(Yanfan), 하이난 춘룽 등 신규 선주가 경험이 적은 조선소에 발주하는 흐름이 눈에 띈다.", "eSum": "Shippax reports 46 PCTC newbuildings were contracted in 2026 as of 15 August, most securing 2029 slots, driven by China's H1 vehicle exports of 5.096m units (+65.5%) and a record 1.037m units in June (+75%). SFL ordered a 7,000 CEU dual-fuel ship at CIMC Raffles (understood chartered long-term to BYD Logistics); Zodiac followed with six at the same yard, and EPS placed three each at China Merchants Jinling and Weihai. Dual-fuel 7,000 CEU newbuild prices are near USD 100m. Notably, first-tier Chinese operators have been replaced by newcomers such as Yanfan Group and Hainan Chunlong ordering at less-experienced yards.", "kImp": "PCTC 신조 사이클의 과열 여부와 2029년 인도 집중에 따른 향후 공급과잉 리스크를 가늠할 핵심 지표. 한국 조선·해운 업계의 선복·선가 전략 판단에 직접 관련.", "eImp": "A key gauge of how hot the PCTC ordering cycle is and the oversupply risk from a 2029 delivery bunching, directly relevant to Korean yard and operator capacity/pricing strategy.", "url": "https://www.shippax.com/en/news/46-pctc-newbuilding-orders-so-far-in-2026.aspx"}, {"code": "PCTC", "title": "회그 오토라이너스 2Q 매출 증가·이익 감소…연료비·중동 차질 여파", "src": "Baird Maritime", "date": "2026-08-20", "kSum": "회그 오토라이너스(Höegh Autoliners)는 2026년 2분기 매출 3억7,600만달러로 전분기(3억6,000만달러) 대비 증가했으나, 상각전영업이익(EBITDA)은 연료·항해·용선료 상승으로 1억4,500만달러에서 1억2,200만달러로 감소했다. 순이익은 8,600만달러로 전분기 1억300만달러에서 줄었다. 수송량은 400만㎥로 2.6% 늘었고 총운임은 CBM당 94.1달러로 1.6% 상승했다. CEO 안드레아스 엥거(Andreas Enger)는 중동 분쟁에도 중국 수출 강세로 선복 타이트닝이 가속됐다고 밝혔다. 5월 초 알라이언스 페어팩스(Alliance Fairfax)호가 해군 호위로 페르시아만을 안전 이탈했으며 현재 역내 운항선은 없다. 3분기 EBITDA는 2분기와 유사할 것으로 전망했다.", "eSum": "Höegh Autoliners posted Q2 2026 revenue of USD 376m, up from USD 360m, but EBITDA fell to USD 122m from USD 145m on higher fuel, voyage and charter-hire costs; net profit was USD 86m (down from USD 103m). Volumes rose 2.6% to 4m cbm and gross rates gained 1.6% to USD 94.1/cbm. CEO Andreas Enger said capacity tightness accelerated in Q2 despite Middle East disruption as China sustained strong export growth. The Alliance Fairfax safely exited the Persian Gulf under naval escort in early May, with no vessels now in the region. Q3 EBITDA is guided in line with Q2.", "kImp": "완성차 해운 시황을 대표하는 상장 선사의 분기 실적으로, 운임·수송량·연료비 추세와 중동 리스크의 손익 영향을 파악하는 벤치마크. (월레니우스 빌헬름센과는 별개 기업)", "eImp": "Quarterly results from a bellwether listed car carrier, benchmarking rate/volume/fuel trends and the P&L impact of Middle East risk. (Separate from Wallenius Wilhelmsen.)", "url": "https://www.bairdmaritime.com/shipping/dry-cargo/pcc-pctc/hoegh-autoliners-revenue-up-profit-down-in-q2-amid-shipping-disruptions"}, {"code": "PCTC", "title": "CM RoRo, 7,800CEU 메탄올 PCTC 2척 곧 인도…26년선 창성훙 4,200만달러 매각", "src": "Shippax", "date": "2026-08-19", "kSum": "중국초상 로로(CM RoRo)는 6월 말·7월 초 진수한 7,800CEU 메탄올 이중연료 PCTC 2척(CM 우한·CM 광저우)을 수주 내 인도받는다. 델타마린(Deltamarin) 설계 76,400GT급으로 그린 메탄올 사용 시 온실가스 70% 이상 감축이 예상되며, 연내 자매선 2척이 추가 인도된다. 이는 안지 인터내셔널 로지스틱스(Anji)와의 협력협정 체결 직후 이뤄져 중국 완성차 수출 급증 시점에 국제 로로 선복을 보강한다. 한편 선대 교체의 일환으로 모회사 CMES는 2000년 울랴니크 조선소 건조 4,310CEU PCTC 창성훙(CHANG SHENG HONG)을 약 2억8,600만위안(약 4,200만달러)에 중국 선주에 매각했는데, 이는 타이트한 자동차선 시장을 반영한 이례적 고가다.", "eSum": "CM RoRo will soon take delivery of two 7,800 CEU methanol dual-fuel PCTCs (CM Wuhan and CM Guangzhou), floated out in late June/early July. The Deltamarin-designed 76,400 GT ships are expected to cut GHG emissions by over 70% on green methanol, with two sisters to follow this year. The additions come just after a cooperation deal with Anji International Logistics, boosting international ro-ro capacity amid China's export surge. Separately, parent CMES sold the 2000-built 4,310 CEU PCTC Chang Sheng Hong for about CNY 286m (~USD 42m), an extraordinary price reflecting the tight car carrier market.", "kImp": "신조 인도(공급 확대)와 26년 노후선의 초고가 매각(자산가치 강세)이 동시에 나타나 시황의 양면을 보여줌. 메탄올 추진 확산 흐름도 시사.", "eImp": "Shows both sides of the market at once: newbuild deliveries adding supply, and a 26-year-old vessel fetching an extraordinary price signaling firm asset values, plus the spread of methanol propulsion.", "url": "https://www.shippax.com/en/news/cm-roro-to-take-delivery-of-two-7800-ceu-methanol-pctcs.aspx"}, {"code": "PCTC", "title": "로로 해운 GHG 배출데이터 감독 신설기구 GRC 위원회 출범", "src": "Shippax", "date": "2026-08-20", "kSum": "글로벌 로로 커뮤니티(GRC)가 전 세계 자동차선 수송선복의 약 80%를 대표하는 부문의 배출데이터 관리를 감독하는 신설 거버넌스 기구 'GRC 위원회(GRCC)'를 출범시켰다. 이 기구는 배출 산정방식과 데이터 관리 관행을 상시 평가하는 공식 체계를 마련해 선사·화주·완성차 제조사에 신뢰성 있고 투명한 온실가스 정보를 제공한다. FuelEU 해사규정, IMO 온실가스 감축, 기업 스코프3 보고 요구가 배출데이터 검증 수요를 키운 배경이다. 선급 ClassNK가 거버넌스 프레임워크와 데이터 처리 프로토콜 개발에 참여했고 독립 검증기관 역할을 맡으며, ClassNK 그린인증부의 히로시 오치(Hiroshi Ochi)가 GRCC 부의장으로 선출됐다.", "eSum": "The Global Ro-Ro Community (GRC) launched the GRC Council (GRCC), a governance body overseeing emissions-data management for a sector representing roughly 80% of global car carrier capacity. It creates a formal structure to continuously assess emissions accounting methods and data practices, giving carriers, cargo owners and OEMs dependable, transparent GHG information. Demand for verified data stems from FuelEU Maritime, IMO GHG initiatives and corporate Scope 3 reporting. Class society ClassNK helped develop the framework and will act as independent verifier, with ClassNK's Hiroshi Ochi elected GRCC Vice-Chair.", "kImp": "자동차선 부문의 탈탄소·규제 대응이 데이터 표준화·검증 체계로 제도화되는 신호. 선급(ClassNK) 참여로 검증 시장 및 화주 스코프3 대응과 직결.", "eImp": "Signals the car carrier sector formalizing decarbonization and regulatory compliance through standardized, verified emissions data; class-society (ClassNK) involvement ties it to verification markets and shipper Scope 3 needs.", "url": "https://www.shippax.com/en/news/new-governance-body-launched-to-oversee-ghg-emissions-data-in-roro-shipping.aspx"}, {"code": "PCTC", "title": "살라움 라인, 유럽 내륙 완성차 물류 자회사 'Sallaum Logistics' 신설", "src": "Shippax", "date": "2026-08-20", "kSum": "살라움 라인(Sallaum Lines)이 리투아니아 빌뉴스에 본사를 둔 유럽 전용 완성차 물류회사 '살라움 로지스틱스(Sallaum Logistics Ltd)'를 신설, 해상 운송 역량을 항만-유통허브-딜러로 이어지는 내륙 배송까지 확장한다. 트럭·트레일러 50대로 출범해 최대 10대 적재 카캐리어를 운용하며 2029년까지 자가 차량을 300대로 늘릴 계획이다. 초기 서비스 대상은 독일·벨기에·네덜란드·스위스·스페인·프랑스·체코·폴란드로, 안트베르펜·브레머하펜·로테르담·마르세유 항만과 내륙을 연결한다. 공장-항만 운송, 국경간 운송, 차량 처리·출고전점검(PDI), 보관 등 종합 서비스를 제공하며 GPS·텔레매틱스 통합도 추진한다.", "eSum": "Sallaum Lines launched Sallaum Logistics Ltd, a dedicated European finished-vehicle logistics company based in Vilnius, Lithuania, extending its ocean expertise into inland distribution from ports to hubs and dealers. It starts with 50 truck-and-trailer units carrying up to ten vehicles each, aiming to grow its owned fleet to 300 trucks by 2029. Initial coverage spans Germany, Belgium, the Netherlands, Switzerland, Spain, France, Czechia and Poland, linking Antwerp, Bremerhaven, Rotterdam and Marseille to inland destinations, with services from factory-to-port transport to PDI and storage, plus GPS/telematics integration.", "kImp": "자동차선 선사의 '해상+내륙' 통합물류 수직계열화 사례로, 완성차 공급망 마지막 구간(라스트마일)까지 장악하려는 업계 전략 변화를 보여줌.", "eImp": "An example of a car carrier vertically integrating ocean plus inland logistics, illustrating the industry's move to control the final leg of the finished-vehicle supply chain.", "url": "https://www.shippax.com/en/news/sallaum-lines-launches-dedicated-european-road-logistics-arm.aspx"}, {"code": "PCTC", "title": "\"중국 완성차 수출이 세계 자동차선 선복을 앞지른다\"", "src": "TheAutoExec", "date": "2026-08-17", "kSum": "테오토이그젝(TheAutoExec)은 지난 선복난에 대응해 발주된 대규모 자동차선 신조가 지금 인도되고 있으나, 중국이 진수 속도에 맞먹는 속도로 이를 채우며 용선료를 다시 끌어올리고 컨테이너 수송까지 유발해 새로운 신조 물결을 촉발하고 있다고 분석했다. 사례로 BYD 정저우(BYD Zhengzhou)호가 6월 2일 멜버른 입항 시 4,809대를 싣고 와 멜버른 1,855대, 시드니 1,519대, 브리즈번 1,435대를 하역했고 약 4분의 3이 도착 전 이미 판매된 물량이었다. 창업자 글렌 버틀러(Glenn Butler)는 2025년 세계 자동차 판매가 약 5% 증가한 가운데 성장의 상당 부분이 중국 수출 주도였을 것으로 추정했다. (회원제 기사)", "eSum": "TheAutoExec argues the wave of car carriers ordered during the last capacity crunch is arriving now, but China is filling them almost as fast as they hit the water, pushing charter rates back up, spilling into container shipping and triggering a fresh newbuild wave. It cites the BYD Zhengzhou, which docked in Melbourne on 2 June with 4,809 vehicles, unloading 1,855 in Melbourne, 1,519 in Sydney and 1,435 in Brisbane, roughly three-quarters pre-sold. Founder Glenn Butler estimates much of 2025's ~5% global vehicle-sales growth was China export-driven. (Membership article.)", "kImp": "신조 인도 러시에도 중국 수출 수요가 선복을 흡수해 시황 강세가 지속되는 구조를 짚은 분석으로, PCTC 공급과잉 우려에 대한 반론적 시각 제공.", "eImp": "An analysis of why the market stays firm despite the delivery rush, as Chinese export demand absorbs new capacity, offering a counterpoint to PCTC oversupply fears.", "url": "https://www.theautoexec.com/autoexec-features/2026/08/17/chinas-car-exports-are-outrunning-the-worlds-vehicle-carrier-fleet/"}]}, {"code": "WW", "type": "news", "kTitle": "Section 5. 발레니우스 빌헬름센", "eTitle": "Section 5. Wallenius Wilhelmsen", "items": [{"code": "WW", "title": "What's Behind Wallenius Wilhelmsen (OB:WAWI) Stock's Latest Move?", "src": "Simply Wall St", "date": "2026-08-15", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)의 2026년 2분기 실적이 매출 감소와 순이익 급감을 기록하면서 수익성과 운영 압박에 대한 의문이 제기되었다. 그럼에도 주가 흐름은 강세로, 최근 30일 수익률 15.79%, 연초 대비 61.99%, 1년 총주주수익률 99.43%를 나타냈다. 가장 널리 추종되는 애널리스트 내러티브는 공정가치를 NOK124로 보아 현재가(NOK162.80) 대비 약 31% 고평가로 판단한 반면, Simply Wall St의 자체 DCF 모델은 NOK342.94로 약 52.5% 저평가라는 상반된 결론을 제시했다.", "eSum": "After Wallenius Wilhelmsen's Q2 2026 earnings showed lower sales and a sharp drop in net income, questions have grown about its profitability and operational pressures. Yet the stock's momentum has stayed strong, with a 30-day return of 15.79%, a year-to-date return of 61.99% and a 1-year total shareholder return of 99.43%. The most-followed analyst narrative pegs fair value at NOK124, implying the stock is roughly 31% overvalued versus its NOK162.80 close, while Simply Wall St's own DCF model points to NOK342.94, or about 52.5% undervalued, a stark divergence in valuation views.", "kImp": "2분기 실적 부진에도 강한 주가 모멘텀과 애널리스트-DCF 간 큰 밸류에이션 괴리는 자동차운반선(PCTC) 시황 사이클과 저배출 신조 선대의 마진 방어력에 대한 시장 견해가 엇갈리고 있음을 보여준다. 투자자·화주 모두 발레니우스 빌헬름센의 현금창출력 지속성을 주시할 필요가 있다.", "eImp": "Despite the soft Q2, strong price momentum and a wide analyst-versus-DCF valuation gap show the market is split on where PCTC market cycles and the margin protection of low-emission newbuilds leave the company. Both investors and shippers should watch the durability of Wallenius Wilhelmsen's cash generation.", "url": "https://simplywall.st/stocks/no/transportation/ob-wawi/wallenius-wilhelmsen-shares/news/whats-behind-wallenius-wilhelmsen-obwawi-stocks-latest-move"}, {"code": "WW", "title": "Does Wallenius Wilhelmsen (OB:WAWI) Prioritize Shareholder Payouts Over Reinvestment After Weaker H1 2026 Earnings?", "src": "Simply Wall St", "date": "2026-08-17", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)은 전년 대비 부진한 2026년 2분기·상반기 실적에도 불구하고 상반기 주당 총 0.61달러의 배당에 더해 1억 달러 규모의 특별배당을 승인했으며, 현금 지급은 2026년 9월 16일경 예정이다. 이익 감소와 이례적으로 높은 주주환원이 겹치면서, 경영진이 재투자 수요·재무 건전성·배당 사이의 균형을 어떻게 잡고 있는지에 대한 의문이 제기되고 있다. Simply Wall St는 순이익 감소 국면에서 높아진 배당성향이 시황 악화 시 재무 유연성을 제약할 위험을 지적했다.", "eSum": "Despite weaker year-on-year Q2 and H1 2026 results, Wallenius Wilhelmsen approved a total H1 ordinary dividend of US$0.61 per share (50% of net profit) plus an additional US$100 million extraordinary payout, with cash distribution scheduled on or about 16 September 2026. The mix of softer earnings and an unusually high cash return raises questions about how management balances reinvestment needs, balance-sheet resilience and income distribution. Simply Wall St flags that a higher payout ratio amid declining net income could leave the company more exposed if shipping markets soften.", "kImp": "실적 둔화 속 대규모 특별배당 결정은 신조 선대 투자와 주주환원 사이에서 경영진의 자본배분 우선순위를 시장이 재평가하게 만드는 사안이다. 발레니우스 빌헬름센의 배당 정책과 재무 여력은 PCTC 시황 변동성 국면에서 리스크·리워드 균형을 가늠하는 핵심 지표가 된다.", "eImp": "Approving a large extraordinary dividend during an earnings slowdown pushes the market to reassess management's capital-allocation priorities between fleet-renewal investment and shareholder returns. Wallenius Wilhelmsen's dividend policy and financial headroom become key gauges of the risk-reward balance amid PCTC market volatility.", "url": "https://simplywall.st/stocks/no/transportation/ob-wawi/wallenius-wilhelmsen-shares/news/does-wallenius-wilhelmsen-obwawi-prioritize-shareholder-payo"}]}, {"code": "EE", "type": "news", "kTitle": "Section 6. 에너지 효율·탈탄소", "eTitle": "Section 6. Energy Efficiency", "items": [{"code": "EE", "title": "싱가포르 벙커링에 캐슈넛 껍질액(CNSL) 첫 혼합 공급", "src": "Splash247", "date": "2026-08-20", "kSum": "올람 아그리(Olam Agri)와 비톨 벙커스(Vitol Bunkers)가 싱가포르 최초로 캐슈넛 껍질액(CNSL)을 공동가공(co-processing)한 VLSFO를 8만2천dwt 캄사르막스 벌크선 사이온 마틸다(Scion Mathilda)에 총 246.5톤(일반 VLSFO 212톤 + CNSL 혼합 34.5톤) 공급했다. 혼합유의 GHG 강도는 2.02 gCO2eq/MJ로, 별도 선상 처리 없이 RMG380 규격을 충족하며 일반 VLSFO 대비 최소 120톤의 CO2 상당량을 절감했다.", "eSum": "Olam Agri and Vitol Bunkers completed Singapore's first bunker supply of VLSFO co-processed with cashew nutshell liquid (CNSL), delivering 246.5 tonnes to the 82,000 dwt kamsarmax Scion Mathilda. The co-processed fuel had a GHG intensity of 2.02 gCO2eq/MJ, met RMG380 grade without special onboard treatment, and saved at least 120 tonnes of CO2-equivalent versus conventional VLSFO.", "kImp": "폐기물 유래 바이오원료의 공동가공은 기존 벙커링 인프라를 그대로 활용해 즉시 탄소집약도를 낮출 수 있는 실용적 감축 경로로, FuelEU·IMO 규제 대응 옵션을 넓힌다.", "eImp": "Waste-derived biofeedstock co-processing offers a drop-in, infrastructure-compatible route to cut carbon intensity immediately, widening compliance options under FuelEU and IMO measures.", "url": "https://splash247.com/cashew-waste-enters-singapore-bunker-mix/"}, {"code": "EE", "title": "ClassNK, 수소·메탄올 연료선 규칙 공백 보완한 개정 가이드라인 발표", "src": "Splash247", "date": "2026-08-20", "kSum": "일본선급(ClassNK)이 '대체연료 사용 선박 가이드라인' 3.1판을 발표해, 5월 MSC 111에서 승인된 IMO 임시 지침(MSC.1/Circ.1701)에 맞춰 수소 요건을 정비하고 베이지안 기법으로 산정한 수소 누출 빈도 추정치를 추가했다. 또한 기존 IMO 지침(MSC.1/Circ.1621)이 다루지 않은 메탄올·에탄올 연료탱크 구조강도 요건을 확충했다.", "eSum": "ClassNK released Edition 3.1 of its Guidelines for Ships Using Alternative Fuels, aligning hydrogen requirements with the IMO interim guidelines (MSC.1/Circ.1701, approved at MSC 111 in May) and adding estimated hydrogen leak frequencies calculated via a Bayesian methodology. It also expanded the methanol/ethanol section with fuel-tank structural strength requirements not covered by existing IMO guidance (MSC.1/Circ.1621).", "kImp": "선급 규칙이 IMO 임시 지침의 공백을 메우면서 수소·메탄올 추진선 설계·승인 경로가 명확해져 대체연료선 발주와 리스크 관리에 직접적 도움을 준다.", "eImp": "Class rules filling IMO interim gaps clarify design and approval pathways for hydrogen and methanol-fuelled ships, directly aiding newbuild ordering and risk management for alternative-fuel vessels.", "url": "https://splash247.com/classnk-fills-gaps-in-hydrogen-and-methanol-ship-rules/"}, {"code": "EE", "title": "상하이항, 세계 최대 규모 그린 메탄올 벙커링 완료", "src": "Seatrade Maritime", "date": "2026-08-18", "kSum": "CMA CGM, SIPG 에너지, 상하이전기(Shanghai Electric)가 1만3천TEU 이중연료 컨테이너선 CMA CGM 오스뮴(Osmium)에 중국산 바이오메탄올 8,016톤을 급유해, 단일 선박 바이오메탄올 벙커링 사상 최대 규모(종전 2026년 3월 3,643톤)를 기록했다. 바이오메탄올은 지린성 타오난 기지에서 생산돼 다롄을 거쳐 상하이로 이송되며 중국의 통합 그린연료 공급망을 보여줬다.", "eSum": "CMA CGM, SIPG Energy and Shanghai Electric completed bunkering of 8,016 tons of domestically produced bio-methanol onto the 13,000 TEU dual-fuel containership CMA CGM Osmium at the Port of Shanghai, a record for the largest single-vessel bio-methanol bunkering (previous benchmark 3,643 tons in March 2026). The bio-methanol was produced at Shanghai Electric's Taonan base in Jilin and moved via Dalian to Shanghai, showcasing an integrated Chinese green-fuel supply chain.", "kImp": "역대 최대 벙커링 규모와 자국 공급망 실증은 그린 메탄올의 상업적 확장성과 아시아 급유 허브 경쟁력을 부각시킨다.", "eImp": "The record bunkering volume and demonstrated domestic supply chain highlight green methanol's commercial scalability and the competitiveness of Asian bunkering hubs.", "url": "https://www.seatrade-maritime.com/bunkering/world-s-largest-green-methanol-bunkering-in-shanghai-port"}, {"code": "EE", "title": "에버렌스·후둥중화, 하이브리드 추진 LNG선 공동개발 협약", "src": "Seatrade Maritime", "date": "2026-08-20", "kSum": "에버렌스(Everllence, 옛 MAN Energy Solutions)가 후둥중화(Hudong-Zhonghua)와 엔지니어링 설계 협약을 맺고, 자사 DFE+(이중연료 전기추진+) 하이브리드-전기 추진을 탑재한 18만㎥급 LNG 운반선을 개발한다. IMO의 강화되는 CII 요건 충족을 겨냥한 것으로, 종전 10척의 재래식 DFDE LNG선 협력을 확장해 고효율 추진을 탈탄소 경로로 제시했다.", "eSum": "Everllence signed an Engineering Design Agreement with Hudong-Zhonghua to develop a 180,000 cbm LNG carrier fitted with Everllence's DFE+ (Dual-Fuel, Electric+) hybrid-electric propulsion, aimed at meeting the IMO's tightening CII requirements. The deal builds on a prior partnership for 10 conventional DFDE LNG carriers, positioning higher-efficiency propulsion as a decarbonization pathway toward net-zero by 2050.", "kImp": "하이브리드-전기 추진은 LNG선의 연비와 CII 등급을 개선하는 실효적 기술로, 강화되는 탄소집약도 규제 대응에서 추진계 최적화의 중요성을 보여준다.", "eImp": "Hybrid-electric propulsion offers a practical route to improve LNG-carrier fuel efficiency and CII ratings, underscoring propulsion optimization as tightening carbon-intensity rules bite.", "url": "https://www.seatrade-maritime.com/shipyards/everllence-and-hudong-zhonghua-in-joint-lng-carrier-propulsion-development"}, {"code": "EE", "title": "발틱 시핑, 풍력보조 하이브리드 연안선 2척 취항", "src": "Container News", "date": "2026-08-20", "kSum": "발틱 시핑 컴퍼니(Baltic Shipping Company)가 다멘(Damen)이 건조한 3,550dwt 신조선 M/V 발틱 아이언(Baltic Iron)과 M/V 발틱 팀버(Baltic Timber)를 상업 운항에 투입했다. 두 선박은 각각 에코윈드(Econowind)의 벤토포일(VentoFoil) 2기와 대용량 배터리팩을 탑재해 연료 소비와 CO2 배출을 최대 12% 절감할 것으로 기대되며, 저배출 운송 수요가 커지는 유럽 근해 시장을 겨냥한다.", "eSum": "Baltic Shipping Company put two new 3,550 DWT Damen-built vessels, M/V Baltic Iron and M/V Baltic Timber, into commercial service, each fitted with two Econowind VentoFoils plus large battery packs, expected to cut fuel consumption and CO2 emissions by up to 12%. The hybrid coasters target the European shortsea market where customers increasingly demand lower-emission transport.", "kImp": "풍력보조 추진과 배터리 하이브리드의 결합은 근해 화물선에서 즉시 적용 가능한 저비용 감축 수단으로, 신조 단계부터 WAPS 채택이 확산되고 있음을 보여준다.", "eImp": "Combining wind-assisted propulsion with battery hybridization is a low-cost, deployable emissions cut for shortsea cargo ships, signaling growing WAPS uptake from the newbuild stage.", "url": "https://container-news.com/baltic-shipping-company-adds-two-wind-assisted-hybrid-vessels/"}, {"code": "EE", "title": "인터뷰: 해운은 그린연료 시장의 최적 수요처지만 폭넓은 확산이 선결과제", "src": "Ship & Bunker", "date": "2026-08-20", "kSum": "유러피언 에너지(European Energy)의 토르벤 뇌르고르는 해운이 그린연료 시장을 스스로 창출하는 데는 취약하나, 도로·산업 등 타 부문이 공급을 확대하면 이를 사들이기에 최적 위치에 있다고 주장하며, 생산량 전량을 판매하는 52MW·연 4만2천톤 규모 카쇠(Kassø) e-메탄올 플랜트를 예로 들었다. 그는 연 약 15만톤의 적합 메탄올이 필요한 독일의 0.1% RFNBO 혼합 의무를 언급하며, 지난해 10월 MEPC에서 IMO 넷제로 프레임워크 채택이 무산되면서 해운이 규제 주도권을 잃었다고 경고했다.", "eSum": "European Energy's Torben Norgaard argues shipping is structurally poor at creating green-fuel markets but well placed to buy into them once other sectors scale supply, citing the 52 MW, 42,000 mt/year Kasso e-methanol plant that sells all it can produce. He notes Germany's new 0.1% RFNBO blending mandate (needing roughly 150,000 mt/year of compliant methanol) and warns shipping lost its regulatory lead after the IMO Net-Zero Framework's adoption collapsed at last October's MEPC.", "kImp": "그린연료 공급 확대는 해운 단독이 아닌 범부문 수요·정책에 좌우되며, IMO 규제 지연은 대체연료 투자 결정의 불확실성을 키운다.", "eImp": "Scaling green-fuel supply depends on cross-sector demand and policy rather than shipping alone, and IMO regulatory delay heightens uncertainty for alternative-fuel investment decisions.", "url": "https://shipandbunker.com/news/world/139269-interview-shipping-perfectly-placed-for-green-fuel-markets-but-broader-adoption-needed-first"}, {"code": "EE", "title": "영국선주협회, 넷제로 5대 그린 경로별 핵심 안전 고려사항 보고서", "src": "SAFETY4SEA", "date": "2026-08-19", "kSum": "영국선주협회(UK Chamber of Shipping)가 바이오연료, 메탄올, 수소, 암모니아, 배터리 에너지저장장치(BESS) 등 5대 주요 탈탄소 연료 경로별 안전 고려사항을 분석한 보고서를 발표했다. 업계 전문성을 토대로 각 경로에서 선주가 직면하는 운항·안전 이슈를 짚었다.", "eSum": "The UK Chamber of Shipping published a report examining safety considerations across five key decarbonization fuel pathways: biofuels, methanol, hydrogen, ammonia and battery energy storage systems. The report draws on industry expertise to flag the operational and safety issues shipowners face on each route to net zero.", "kImp": "연료 전환의 병목은 기술뿐 아니라 안전 규정·운용 역량이며, 경로별 안전 리스크의 체계적 정리는 선주의 연료 선택 의사결정을 뒷받침한다.", "eImp": "Fuel-transition bottlenecks are as much about safety rules and operational capability as technology; a structured view of per-pathway risks supports shipowners' fuel-choice decisions.", "url": "https://safety4sea.com/uk-chamber-of-shipping-key-safety-considerations-for-five-green-paths-to-net-zero/"}, {"code": "EE", "title": "클린십핑얼라이언스·마린퓨얼얼라이언스, 배출 규제 준수 협력 MOU", "src": "SAFETY4SEA", "date": "2026-08-19", "kSum": "클린 십핑 얼라이언스(CSA)와 마린 퓨얼 얼라이언스(MFA)가 해운업계와 벙커 공급업체의 배출 규제 요건 충족을 지원하기 위한 양해각서(MOU)를 체결했다. 이 협력은 대체연료 및 배출 저감 기술로의 전환을 촉진하는 것을 목표로 한다.", "eSum": "The Clean Shipping Alliance (CSA) and the Marine Fuels Alliance (MFA) signed a Memorandum of Understanding to help the shipping industry and bunker suppliers meet emissions regulatory requirements. The partnership aims to advance the transition to alternative fuels and emissions-reduction technologies.", "kImp": "선주와 연료 공급망을 잇는 협력은 규제 준수의 실행 격차를 좁히고 대체연료·저감기술 도입 속도를 높이는 데 기여한다.", "eImp": "Aligning shipowners with the fuel supply chain narrows the compliance implementation gap and can accelerate uptake of alternative fuels and abatement technologies.", "url": "https://safety4sea.com/clean-shipping-alliance-and-marine-fuels-alliance-team-up-on-emissions-compliance/"}]}, {"code": "DIG", "type": "news", "kTitle": "Section 7. 디지털라이제이션", "eTitle": "Section 7. Digitalization", "items": [{"code": "DIG", "title": "Scorpio Tankers reports zero cyber incidents as vessel systems become more connected", "src": "The Digital Ship", "date": "2026-08-20", "kSum": "스콜피오 탱커스(Scorpio Tankers)는 선박 시스템의 연결성이 높아지는 가운데 2025년 사이버 사고 '제로'를 기록했다고 보고했다. 위성 연결과 OT 시스템 통합이 확대되면서 공격 표면이 커지는 상황에서, 계층적 방어와 상시 모니터링을 통해 무사고를 달성했다.", "eSum": "Scorpio Tankers reported zero cyber incidents in 2025 even as its vessel systems became more connected. As satellite connectivity and OT integration widen the attack surface, the operator credited layered defenses and continuous monitoring for the clean record.", "kImp": "선대 디지털화가 가속되는 만큼 사이버 회복력이 운항 신뢰성의 핵심 지표가 된다. 선주는 secure-by-design과 지속 모니터링 체계 투자를 검토해야 한다.", "eImp": "As fleet digitalization accelerates, cyber resilience becomes a core reliability metric. Owners should weigh investment in secure-by-design architecture and continuous monitoring.", "url": "https://thedigitalship.com/news/maritime-satellite-communications/scorpio-tankers-reports-zero-cyber-incidents-as-vessel-systems-become-more-connected/"}, {"code": "DIG", "title": "CIMAC says 200-microsecond ship systems need digital-ready regulation", "src": "The Digital Ship", "date": "2026-08-20", "kSum": "국제내연기관회의(CIMAC)는 200마이크로초 단위로 반응하는 최신 선박 제어 시스템에 맞춰 규제도 '디지털 대응형'으로 전환돼야 한다고 지적했다. 고속 자동화·전자 제어가 확산되면서 기존 규정 체계가 기술 속도를 따라가지 못한다는 문제의식이다.", "eSum": "CIMAC argued that regulation must become digital-ready to match modern ship control systems that respond in 200 microseconds. As high-speed automation and electronic control spread, existing rule frameworks are struggling to keep pace with the technology.", "kImp": "디지털·자동화 선박 규제 정비가 지연되면 도입 불확실성이 커진다. 기관·클래스는 실시간 제어 시스템에 맞는 규정 현대화를 서둘러야 한다.", "eImp": "Lagging rules for digital and automated ships raise adoption uncertainty. Authorities and class societies should accelerate rule modernization for real-time control systems.", "url": "https://thedigitalship.com/news/electronics-navigation/cimac-says-200-microsecond-ship-systems-need-digital-ready-regulation/"}, {"code": "DIG", "title": "TGS moves 10TB of seismic data a day with all-LEO connectivity from Speedcast", "src": "The Digital Ship", "date": "2026-08-20", "kSum": "지구물리 데이터 기업 TGS는 스피드캐스트(Speedcast)의 전면 LEO(저궤도 위성) 연결을 도입해 하루 10TB 규모의 탄성파 데이터를 전송하고 있다. 고대역 저지연 위성망으로 해상 대용량 데이터 처리와 원격 협업이 가능해졌다.", "eSum": "TGS is moving 10TB of seismic data a day using all-LEO connectivity from Speedcast. The high-bandwidth, low-latency satellite network enables large-scale offshore data handling and remote collaboration.", "kImp": "LEO 위성망이 해상 대용량 데이터 워크플로우를 실용화하며 원격운영·클라우드 연계를 가속한다. 데이터 집약 선대의 연결성 전략 재설계가 필요하다.", "eImp": "LEO networks make heavy offshore data workflows practical, accelerating remote operations and cloud integration. Data-intensive fleets should rethink connectivity strategy.", "url": "https://thedigitalship.com/news/maritime-satellite-communications/tgs-moves-10tb-of-seismic-data-a-day-with-all-leo-connectivity-from-speedcast/"}, {"code": "DIG", "title": "S-100 data sources could reshape how shipowners manage navigation", "src": "The Digital Ship", "date": "2026-08-19", "kSum": "안쉬츠(Anschutz)와 텔레다인 세븐씨스(Teledyne SevenCs)의 협력으로 S-100 표준 데이터 통합이 차세대 ECDIS의 핵심으로 자리잡고 있다. 다양한 수로·환경 데이터 계층을 통합해 선주의 항해 관리 방식이 근본적으로 바뀔 전망이다.", "eSum": "A partnership between Anschutz and Teledyne SevenCs puts S-100 data integration at the heart of next-generation ECDIS. By combining multiple hydrographic and environmental data layers, it could reshape how shipowners manage navigation.", "kImp": "S-100 전환은 e-내비게이션 고도화의 분기점으로, 항해 안전과 데이터 기반 의사결정을 강화한다. 선사는 ECDIS 업그레이드 로드맵을 준비해야 한다.", "eImp": "The S-100 shift is a turning point for e-navigation, strengthening safety and data-driven decisions. Operators should prepare ECDIS upgrade roadmaps.", "url": "https://thedigitalship.com/news/electronics-navigation/s-100-data-sources-could-reshape-how-shipowners-manage-navigation/"}, {"code": "DIG", "title": "Descartes brings AI document processing into customs and shipment workflows", "src": "The Digital Ship", "date": "2026-08-19", "kSum": "데카르트(Descartes)는 통관·선적 업무 흐름에 AI 문서 처리 기능을 도입했다. 반복적인 무역 서류 처리를 자동화해 오류를 줄이고 물류 처리 속도를 높이는 것이 목표다.", "eSum": "Descartes has brought AI document processing into customs and shipment workflows. The tool automates repetitive trade paperwork to cut errors and speed up logistics handling.", "kImp": "AI 기반 문서 자동화가 물류·통관의 병목을 완화하며 운영 효율을 끌어올린다. 선사·포워더는 백오피스 자동화 도입을 검토할 만하다.", "eImp": "AI document automation eases logistics and customs bottlenecks, lifting operational efficiency. Carriers and forwarders should consider back-office automation.", "url": "https://thedigitalship.com/news/maritime-software/descartes-brings-ai-document-processing-into-customs-and-shipment-workflows/"}, {"code": "DIG", "title": "Singapore's maritime startup push puts 170 companies into the digitalisation pipeline", "src": "The Digital Ship", "date": "2026-08-18", "kSum": "싱가포르 해사항만청(MPA) 주도의 해양 스타트업 육성 정책이 약 170개 기업을 디지털화 파이프라인에 편입시켰다. 항만·선박 디지털 기술 생태계를 확장해 혁신 기술의 상용화를 촉진한다.", "eSum": "Singapore's maritime startup push, led by MPA, has placed around 170 companies into its digitalisation pipeline. The effort expands the port and vessel technology ecosystem and speeds commercialization of innovations.", "kImp": "국가 차원의 스타트업 파이프라인은 해양 디지털 기술의 검증·확산을 가속한다. 아시아 허브 항만의 디지털 경쟁력이 한층 강화될 전망이다.", "eImp": "A national startup pipeline accelerates validation and diffusion of maritime digital tech. Asian hub ports stand to strengthen their digital competitiveness.", "url": "https://thedigitalship.com/news/electronics-navigation/singapores-maritime-startup-push-puts-170-companies-into-the-digitalisation-pipeline/"}, {"code": "DIG", "title": "X-Press Feeders to implement berth planning tech", "src": "Smart Maritime Network", "date": "2026-08-18", "kSum": "엑스프레스 피더스(X-Press Feeders)는 포트체인 커넥트(Portchain Connect)를 도입해 컨테이너 터미널과의 선석 정렬·조율을 개선한다. 네트워크 전반의 선석 계획을 디지털화해 기항 효율을 높인다.", "eSum": "X-Press Feeders will deploy Portchain Connect to improve berth alignment and coordination with container terminals across its network. Digitalising berth planning aims to boost port-call efficiency.", "kImp": "선석 계획 디지털화는 기항 지연과 대기 시간을 줄여 선대 가동률을 높인다. 선사-터미널 데이터 연계가 항만 디지털화의 핵심 축으로 부상한다.", "eImp": "Digital berth planning reduces port-call delays and waiting time, improving fleet utilization. Carrier-terminal data links emerge as a key axis of port digitalization.", "url": "https://smartmaritimenetwork.com/2026/08/18/x-press-feeders-to-implement-berth-planning-tech/"}, {"code": "DIG", "title": "MPA Singapore launches safety and autonomy initiatives", "src": "Smart Maritime Network", "date": "2026-08-18", "kSum": "싱가포르 해사항만청(MPA)은 니어미스(near miss) 보고, 항만 운영, 자율운항 선박 시범사업을 아우르는 3대 이니셔티브를 출범했다. 안전 데이터 활용과 자율운항 기술 실증을 동시에 추진한다.", "eSum": "The Maritime and Port Authority of Singapore (MPA) launched three initiatives covering near-miss reporting, port operations and autonomous vessel trials. The package pairs safety-data use with autonomy technology demonstration.", "kImp": "규제기관 주도의 자율운항 실증과 안전 데이터 체계는 상용화 기반을 다진다. 자율·디지털 선박 도입의 제도적 신뢰성이 높아진다.", "eImp": "Regulator-led autonomy trials and safety-data schemes build the foundation for commercialization. Institutional confidence in autonomous and digital ships rises.", "url": "https://smartmaritimenetwork.com/2026/08/18/mpa-singapore-launches-safety-and-autonomy-initiatives/"}, {"code": "DIG", "title": "Stolt Tankers puts 100 vessels on Procureship platform as fleet procurement goes digital", "src": "The Digital Ship", "date": "2026-08-17", "kSum": "스톨트 탱커스(Stolt Tankers)는 약 100척의 심해 선박을 프로큐어십(Procureship) e-조달 플랫폼으로 이전하며 자체 개발 시스템을 대체했다. 입찰·계약·구매를 단일 디지털 시스템으로 통합하고 반복 구매에 자동화를 적용한다.", "eSum": "Stolt Tankers has moved around 100 deep-sea vessels onto Procureship's e-procurement platform, replacing its in-house system. The deal unifies tenders, contracts and purchasing in one digital system with automation for routine buying.", "kImp": "대형 선사의 조달 디지털 전환은 비용 절감과 데이터 기반 구매를 가속한다. 자체 시스템 대신 전문 플랫폼 채택 추세가 확산될 전망이다.", "eImp": "A major operator's procurement digitalization accelerates cost savings and data-driven buying. The shift from in-house tools to specialist platforms is likely to spread.", "url": "https://thedigitalship.com/news/maritime-software/stolt-tankers-puts-100-vessels-on-procureship-platform-as-fleet-procurement-goes-digital/"}]}, {"code": "TECH", "type": "news", "kTitle": "Section 8. 선박관리 기술", "eTitle": "Section 8. Ship Manager Technical", "items": [{"code": "TECH", "title": "ClassNK·삼성중공업·에버그린·웨더뉴스, AI 자율운항 기반 GHG 감축 검증 MOU 체결", "src": "MarineLink", "date": "2026-08-20", "kSum": "ClassNK(일본선급)가 삼성중공업(Samsung Heavy Industries)의 자율운항 시스템 'Samsung Autonomous Ship(SAS)', 웨더뉴스(Weathernews)의 기상·해양 데이터, 에버그린(Evergreen Marine)의 실제 운항 컨테이너선을 활용해 AI 기반 항로 최적화의 연료·온실가스(GHG) 감축 효과를 객관적으로 검증하는 공동 프로젝트 MOU를 체결했다. ClassNK는 검증 방법론을 기술 검토하고 사실확인서(SoF)를 발급한다.", "eSum": "ClassNK has signed an MOU with Samsung Heavy Industries, Evergreen Marine and Weathernews to objectively verify fuel and GHG reductions from AI-based voyage optimization, using SHI's Samsung Autonomous Ship (SAS) system on a live Evergreen containership. ClassNK will review the methodology and issue a Statement of Fact.", "kImp": "선박관리 기술팀 관점에서 AI 항로 최적화의 실선 검증은 CII 등 에너지효율 규제 대응과 연료비 절감의 실증 근거가 되며, 제3자(선급) 검증으로 신뢰성을 확보한다.", "eImp": "For technical managers, third-party (class) verification of AI routing on a live vessel provides credible evidence for CII compliance and fuel savings.", "url": "https://www.marinelink.com/news/mou-signed-verify-emissions-reduction-542294"}, {"code": "TECH", "title": "World Maritime Forum 2027, 코펜하겐서 선대 투자·기술 전환 의제 다룬다", "src": "MarineLink", "date": "2026-08-20", "kSum": "IGGS 그룹이 주최하는 World Maritime Forum 2027이 2027년 2월 23~24일 코펜하겐 AC Bella Sky에서 열린다. 선주·선박관리사·조선소·항만을 대상으로 IMO 규제, EU ETS·FuelEU Maritime, 대체연료·벙커링, 레트로핏 성과, 사이버·GNSS 보안, 선원 육성, AI, 자율운항 등 12개 신규 패널을 예고했다.", "eSum": "World Maritime Forum 2027, organised by IGGS Group, will be held 23-24 Feb 2027 in Copenhagen, featuring 12 panels on IMO measures, EU ETS/FuelEU, alternative fuels and bunkering, retrofit results, cyber/GNSS security, crew development, AI and autonomous operations.", "kImp": "기술관리 의사결정(선대 투자·레트로핏·자율운항 도입)이 규제·재무와 얽히는 흐름을 보여주는 업계 어젠다로, 향후 투자 우선순위 파악에 유용하다.", "eImp": "Signals how technical decisions (fleet investment, retrofit, autonomy) are intertwined with regulation and finance, useful for setting investment priorities.", "url": "https://www.marinelink.com/news/world-maritime-forum-address-shippings-542297"}, {"code": "TECH", "title": "해상 배터리 확산과 핵심광물 공급망, 새로운 투자 이슈로 부상", "src": "MarineLink", "date": "2026-08-18", "kSum": "배터리가 페리·항만작업선·예인선·해양지원선(OSV) 등에서 해운 탈탄소의 실질적 수단으로 자리잡으면서 배터리 공급망과 핵심광물 조달이 새로운 투자·리스크 이슈로 부상하고 있다. 2026년 중반 기준 118개사 156종의 선박용 배터리 시스템이 상용화되었다.", "eSum": "As batteries become a practical part of maritime decarbonization across ferries, harbour craft, tugs and OSVs, battery supply chains and critical-mineral sourcing are emerging as an investment and risk question. As of mid-2026, 156 systems from 118 manufacturers are commercially available.", "kImp": "하이브리드·전기 추진 도입을 검토하는 관리선사에 배터리 조달 안정성과 열폭주 안전 관리가 기술·구매 의사결정 요소가 된다.", "eImp": "Battery sourcing stability and thermal-runaway safety become technical and procurement factors for managers considering hybrid/electric propulsion.", "url": "https://www.marinelink.com/news/critical-minerals-sea-battery-supply-542193"}, {"code": "TECH", "title": "Portchain·X-Press Feeders, 피더 선대에 디지털 솔루션 도입 제휴", "src": "MarineLink", "date": "2026-08-18", "kSum": "디지털 선석·기항 최적화 업체 Portchain과 세계 최대 피더 선사 X-Press Feeders가 피더 시장에 디지털 솔루션을 도입하기 위한 파트너십을 발표했다. 기항 계획과 선석 협업의 효율화를 목표로 한다.", "eSum": "Portchain, a digital port-call and berth-planning provider, and feeder operator X-Press Feeders announced a partnership to deploy digital solutions in the feeder market, aiming to improve port-call planning and berth collaboration.", "kImp": "기항 스케줄·선석 협업의 디지털화는 정시성·연료효율 향상으로 이어져 선박 운항·기술관리 효율에 기여한다.", "eImp": "Digitalising port-call and berth planning improves schedule reliability and fuel efficiency, supporting operational and technical management.", "url": "https://www.marinelink.com/news/portchain-xpress-feeders-partner-542216"}, {"code": "TECH", "title": "ALMACO, 로열캐리비안 'Liberty of the Seas' 대규모 현대화 완료", "src": "MarineLink", "date": "2026-08-19", "kSum": "ALMACO 그룹이 로열캐리비안 인터내셔널(Royal Caribbean International)의 크루즈선 'Liberty of the Seas'에 대한 대규모 현대화 프로젝트를 완료했다. 신규 케이터링 설비 등을 포함한다.", "eSum": "ALMACO Group completed a major modernization project aboard Royal Caribbean International's Liberty of the Seas, delivering new catering and other facilities.", "kImp": "선령이 높은 선박의 개조·현대화 사례로, 기술관리 부서의 대규모 리퍼비시먼트 계획 수립에 참고가 된다.", "eImp": "A reference case for large-scale refurbishment planning by technical management teams.", "url": "https://www.marinelink.com/news/almaco-completes-liberty-seas-542224"}, {"code": "TECH", "title": "한국발 컨테이너선, 유럽행 북극항로 시범 운항 나서", "src": "MarineLink", "date": "2026-08-19", "kSum": "한 컨테이너선이 한국에서 유럽으로 북극항로를 통해 출항해, 해빙으로 열린 항로의 상업적 활용 가능성을 시험한다.", "eSum": "A containership departs South Korea bound for Europe via the Arctic, testing whether the route opened by melting sea ice can be commercially viable.", "kImp": "북극항로는 운항거리 단축 잠재력과 함께 빙해 항해·선체·기관 리스크 등 기술관리 과제를 동반한다.", "eImp": "The Arctic route offers shorter distances but brings ice-navigation and hull/machinery risks for technical management.", "url": "https://www.marinelink.com/news/south-korean-container-ship-test-arctic-542255"}, {"code": "TECH", "title": "선주·운항자를 위한 실무적 해양 탈탄소 규제 준수 전략", "src": "MaritimeCyprus", "date": "2026-08-20", "kSum": "선주·운항자가 직면한 해양 탈탄소 규제(IMO·EU 등) 대응을 위한 실무적 컴플라이언스 전략을 정리한 기고로, 규제 준수와 운영 효율을 병행하는 접근을 제시한다.", "eSum": "A practical guide to compliance strategies for shipowners and operators facing maritime decarbonization regulations (IMO, EU), balancing regulatory adherence with operational efficiency.", "kImp": "기술관리 부서가 CII·EU ETS·FuelEU Maritime 등 규제 대응 로드맵을 수립하는 데 실무 지침이 된다.", "eImp": "Provides practical guidance for technical teams building compliance roadmaps for CII, EU ETS and FuelEU Maritime.", "url": "https://maritimecyprus.com/2026/08/20/navigating-maritime-decarbonization-practical-compliance-strategies-for-shipowners-and-operators/"}]}, {"code": "HR", "type": "news", "kTitle": "Section 9. 해기인력·선원", "eTitle": "Section 9. Marine HR", "items": [{"code": "HR", "title": "필리핀 선원들, 글로벌 분쟁의 최전선에 서다", "src": "Seatrade Maritime", "date": "2026-08-17", "kSum": "세계 최대 선원 공급국인 필리핀의 선원(Filipino seafarers)들이 호르무즈 해협·홍해 등 지정학적 분쟁 수역과 제재·다크플릿(dark fleet) 이슈의 최전선에 노출되어 있다는 분석이다. 분쟁 격화로 이들의 안전·복지 우려가 커지고 있다.", "eSum": "Seafarers from the Philippines, the world's largest supply nation, are increasingly on the frontline of geopolitical conflicts such as the Strait of Hormuz and the Red Sea, and exposed to sanctions and dark-fleet risks, raising safety and welfare concerns.", "kImp": "선원관리(HR) 측면에서 분쟁 수역 배승 정책, 위험수당, 심리 지원 등에 대한 재검토 필요성을 시사한다.", "eImp": "Signals the need to review deployment policy, hazard pay and psychological support for crews operating in conflict zones.", "url": "https://www.seatrade-maritime.com/crewing/filipino-seafarers-on-the-frontline-global-conflicts"}, {"code": "HR", "title": "Crew Connect Global 2026, 선원관리 핵심 과제 조명", "src": "Seatrade Maritime", "date": "2026-08-17", "kSum": "10월 마닐라에서 열리는 Crew Connect Global 2026을 앞두고 사관 부족의 숨은 비용, 선원 유기(abandonment)·형사화 증가, 신기술 대응 훈련, 근로·휴식시간 규제와 실제의 괴리 등 선원관리 핵심 과제가 제시됐다. Wilhelmsen Ship Management, Anglo-Eastern, Columbia Shipmanagement 등 주요 선박관리사가 참여한다.", "eSum": "Ahead of Crew Connect Global 2026 (October, Manila), key crew-management challenges were highlighted: the hidden costs of the officer shortage, rising abandonment and criminalisation of seafarers, training crews for new technologies, and the gap between rest-hour rules and reality. Major managers including Wilhelmsen, Anglo-Eastern and Columbia Shipmanagement are participating.", "kImp": "선박관리사의 채용·유지·훈련 전략과 휴식시간 규제 준수 개선 과제를 종합적으로 짚어준다.", "eImp": "Frames recruitment, retention, training and rest-hour compliance priorities for ship managers.", "url": "https://www.seatrade-maritime.com/event-news/crew-management-challenges-under-spotlight-at-crew-connect-global-2026"}]}, {"code": "HSEQ", "type": "news", "kTitle": "Section 10. HSEQ·손해방지", "eTitle": "Section 10. HSEQ", "items": [{"code": "HSEQ", "title": "GNSS 교란의 해상안전 영향 보고서 발간 (RIN)", "src": "IIMS", "date": "2026-08-20", "kSum": "왕립항법학회(Royal Institute of Navigation, RIN) 해상 GNSS 교란 워킹그룹이 100여 명의 전문가와 300여 명의 선장 설문을 토대로 GNSS 재밍·스푸핑의 해상안전 영향 보고서를 발간했다. 2025년 발트해·호르무즈·홍해에서 GNSS 교란 관련 충돌·좌초가 보고됐으며, GMDSS 등 SOLAS 필수 장비의 취약성과 사이버보안 리스크를 경고했다.", "eSum": "The Royal Institute of Navigation's Maritime GNSS Interference Working Group published a report on the safety impacts of GNSS jamming and spoofing, based on surveys of 100+ experts and 300+ ship captains. It warns of vulnerabilities in GMDSS and other SOLAS-mandated equipment and frames interference as a cybersecurity risk; at least two GNSS-linked collisions/groundings were reported in 2025.", "kImp": "항해장비가 GNSS에 깊이 의존하는 만큼, 관리선사는 교란 수역 항해 절차·백업 항법·사이버 대응을 SMS에 반영해야 한다.", "eImp": "As navigation equipment depends heavily on GNSS, managers should embed interference-area navigation procedures, backup navigation and cyber measures into the SMS.", "url": "https://www.iims.org.uk/report-into-the-impacts-of-gnss-interference-on-maritime-safety-published/"}, {"code": "HSEQ", "title": "화물창 화재 조기탐지 기술, CFLII 이니셔티브서 검증 진행", "src": "IIMS", "date": "2026-08-20", "kSum": "Safetytech Accelerator가 UK P&I Club·TT Club 등과 함께 추진하는 Cargo Fire & Loss Innovation Initiative(CFLII)가 컨테이너 화물창 화재 조기탐지·화물유실 방지 기술을 실운항 조건에서 검증하고 있다. 3년차에는 덴마크소방연구소에서 대규모 화재실험(배터리 화재·열폭주 포함)이 진행 중이며, LoRaWAN 무선연결과 컨테이너 내 센서에 대한 Lloyd's Register 인증이 추진되고 있다.", "eSum": "The Cargo Fire & Loss Innovation Initiative (CFLII), delivered by Safetytech Accelerator with the UK P&I Club and TT Club, is validating early cargo-fire detection and loss-prevention technologies under operational conditions. Year-3 work includes large-scale fire trials at the Danish Fire Institute (covering battery fires and thermal runaway) and Lloyd's Register certification of LoRaWAN connectivity and an in-container sensor.", "kImp": "컨테이너선 화재는 대형 손실 위험이 큰 만큼, 다층적 조기탐지와 인증된 선내 무선연결 인프라 도입이 HSEQ·기술관리 과제로 부상한다.", "eImp": "With container fires a major loss risk, layered early detection and certified onboard wireless infrastructure become HSEQ/technical priorities.", "url": "https://www.iims.org.uk/cargo-fire-initiative-examines-technology-for-earlier-detection/"}, {"code": "HSEQ", "title": "미 법무부(DOJ), 미신고 선박 결함에 중징계 벌금 부과", "src": "MaritimeCyprus", "date": "2026-08-19", "kSum": "미국 법무부(U.S. DOJ)가 선박 결함(defects) 미신고 사례에 대해 중징계 벌금을 부과했다. 결함·오작동을 은폐하거나 보고하지 않을 경우의 형사·재정적 책임을 부각하며, 투명한 보고와 손실예방 문화의 중요성을 강조하는 사례로 다뤄졌다.", "eSum": "The U.S. Department of Justice imposed heavy fines over unreported ship defects, highlighting the criminal and financial consequences of concealing or failing to report defects/malfunctions, and underscoring the importance of transparent reporting and a loss-prevention culture.", "kImp": "관리선사는 결함·비상 상황의 정직한 보고 절차와 준법 리스크 관리(특히 미국 기항 시)를 강화해야 한다.", "eImp": "Managers must strengthen honest defect/incident reporting procedures and compliance risk management, especially for US port calls.", "url": "https://maritimecyprus.com/2026/08/19/from-crisis-to-conviction-u-s-doj-imposes-heavy-fines-for-unreported-ship-defects/"}, {"code": "HSEQ", "title": "ClassNK, '인간 중심'의 미래 해상안전 관점 제시", "src": "MaritimeCyprus", "date": "2026-08-17", "kSum": "ClassNK(일본선급)가 자동화·디지털화가 확대되는 가운데에서도 인적요소(human factors)를 중심에 둔 미래 해상안전 접근을 제시했다. 기술 발전과 인간의 역할·역량을 결합하는 안전관리 방향을 강조했다.", "eSum": "ClassNK offered a human-centred perspective on the future of maritime safety, stressing that human factors and competency must remain central even as automation and digitalization expand.", "kImp": "SMS·안전문화 설계에서 기술 도입과 함께 인적요소·역량 관리를 균형 있게 반영해야 함을 시사한다.", "eImp": "Reinforces balancing technology adoption with human-factors and competency management in SMS and safety-culture design.", "url": "https://maritimecyprus.com/2026/08/17/classnk-offers-human-perspective-on-the-future-of-maritime-safety/"}]}, {"code": "KR", "type": "news", "kTitle": "Section 11. 한국 해운시장", "eTitle": "Section 11. Korean Shipping Market", "items": [{"code": "KR", "title": "국내 대형 해운사 2분기 호실적…HMM·팬오션·현대글로비스 이익률 개선", "src": "쉬핑뉴스넷(Shipping Newsnet)", "date": "2026-08-18", "kSum": "신영증권 분석에 따르면 국내 상장 대형 해운사 3곳이 모두 2분기 호실적을 발표했다. HMM(에이치엠엠) 영업이익률 10.4%, 팬오션(Pan Ocean) 10.1%, 현대글로비스(Hyundai Glovis) 5.7%를 기록했다. 지난 2월 말 발생한 미국-이란 전쟁으로 호르무즈 해협 통과가 어려워지면서 해상운임과 톤마일이 동반 상승한 것이 실적을 견인했다. 자동차·컨테이너·석탄·곡물 물동량이 모두 강세를 보였고 하반기에도 운임 강세가 이어질 것으로 전망됐다.", "eSum": "Per Shinyoung Securities, all three listed major Korean carriers posted strong Q2 results, with operating margins of 10.4% (HMM), 10.1% (Pan Ocean) and 5.7% (Hyundai Glovis). The late-February US-Iran war made Strait of Hormuz transits difficult, lifting freight rates and ton-miles. Car, container, coal and grain volumes were all firm, with rate strength expected to persist into H2.", "kImp": "지정학 리스크가 오히려 국적 선사의 수익성을 끌어올리는 구조가 재확인됐다. 다만 리스크 해소 시 드라이벌크를 제외한 부문의 운임 조정 가능성에 유의할 필요가 있다.", "eImp": "Confirms how geopolitical risk is paradoxically boosting Korean carriers' profitability; watch for rate correction outside dry bulk if tensions ease.", "url": "http://www.shippingnewsnet.com/news/articleView.html?idxno=71627"}, {"code": "KR", "title": "대한해운, 안정적 실적에 LNG선 기대감…2분기 말 현금성자산 약 3천억원", "src": "쉬핑뉴스넷(Shipping Newsnet)", "date": "2026-08-20", "kSum": "대한해운(Korea Line)이 장기 전용선 계약을 기반으로 안정적 실적 흐름을 이어가고 있으며, 향후 LNG선 사업 확대에 따른 성장 기대감도 부각되고 있다. 회사는 2분기 말 기준 약 3,000억원의 현금성 자산을 보유해 재무 여력이 넉넉한 것으로 나타났다.", "eSum": "Korea Line continues to post stable earnings backed by long-term contract-of-affreightment business, with added upside expected from expanding LNG carrier operations. The company held about KRW 300bn in cash and cash equivalents at end-Q2, underscoring ample financial headroom.", "kImp": "장기계약 비중이 높은 대한해운은 시황 변동에 대한 방어력이 크며, 풍부한 현금은 신조·인수 등 성장투자 여력을 시사한다.", "eImp": "Korea Line's high share of long-term contracts offers strong defensiveness, while its cash pile signals capacity for newbuild or M&A growth investment.", "url": "http://www.shippingnewsnet.com/news/articleView.html?idxno=71665"}, {"code": "KR", "title": "국적 컨테이너선 첫 북극항로 도전…22일 '팬스타 아크로호' 출항", "src": "쉬핑뉴스넷(Shipping Newsnet)", "date": "2026-08-20", "kSum": "우리나라 컨테이너선이 북극항로를 향한 첫 항해에 나선다. '팬스타 아크로(Pan Star Acro)'호가 오는 22일 출항해 약 45일간 북동항로(북극항로) 왕복 시범운항을 수행한다. 부산시와 팬스타(Pan Star)가 손잡고 추진하는 사업으로, 해양수도 도약을 위한 전략적 시범운항으로 평가된다.", "eSum": "A Korean containership will make the country's first Arctic voyage. The 'Pan Star Acro' departs on the 22nd for a roughly 45-day round-trip demonstration on the Northern Sea Route. Jointly promoted by Busan City and Pan Star, it is seen as a strategic pilot toward Busan's maritime-hub ambitions.", "kImp": "북극항로 상업화 가능성을 국적선으로 직접 검증하는 첫 사례로, 향후 아시아-유럽 물류 대체노선 확보 측면에서 상징성이 크다.", "eImp": "First Korean-flag test of Arctic route commercial viability; symbolically significant for securing an alternative Asia-Europe logistics corridor.", "url": "http://www.shippingnewsnet.com/news/articleView.html?idxno=71675"}, {"code": "KR", "title": "해양수산부 국·과장급 인사…국립해양조사원장에 장묘인 승진 발령", "src": "쉬핑뉴스넷(Shipping Newsnet)", "date": "2026-08-21", "kSum": "해양수산부(MOF)가 국·과장급 인사를 단행했다. 국립해양조사원장에 장묘인 수산정책과장을 승진 발령하는 등 주요 보직에 대한 인사 이동이 이뤄졌다.", "eSum": "Korea's Ministry of Oceans and Fisheries (MOF) carried out a director-general/director-level reshuffle, including the promotion of the head of the Fisheries Policy Division to Director of the Korea Hydrographic and Oceanographic Agency.", "kImp": "해수부 조직 개편 및 정책 추진 동력과 연결되는 인사로, 해양조사·수산정책 분야 방향성을 가늠할 수 있다.", "eImp": "The reshuffle signals policy direction and momentum for MOF's hydrographic and fisheries-policy agendas.", "url": "http://www.shippingnewsnet.com/news/articleView.html?idxno=71682"}, {"code": "KR", "title": "현대식 LNG선 스팟 용선료, 선복 공급 증가로 연초 이후 최저", "src": "쉬핑뉴스넷(Shipping Newsnet)", "date": "2026-08-21", "kSum": "현대식 LNG(액화천연가스) 운반선의 스팟 용선료가 신조선 인도에 따른 선복 공급 증가로 올해 들어 최저 수준까지 하락했다. 대량 인도가 이어지면서 단기 시장의 수급 불균형이 용선료 약세로 나타나고 있다.", "eSum": "Spot charter rates for modern LNG carriers have fallen to their lowest level this year as a wave of newbuild deliveries boosts available tonnage. Heavy deliveries are creating a short-term supply-demand imbalance that is weighing on rates.", "kImp": "친환경 LNG선 시장의 단기 공급 과잉 신호로, 신조 발주 붐의 후행 효과가 용선 시황에 부담을 주기 시작했음을 보여준다.", "eImp": "A near-term oversupply signal in the LNG carrier market, showing the lagged impact of the newbuild ordering boom starting to pressure charter rates.", "url": "http://www.shippingnewsnet.com/news/articleView.html?idxno=71681"}, {"code": "KR", "title": "'美·남미 호조' 컨테이너 운임지수 6주 만에 3300선 복귀", "src": "코리아쉬핑가제트(KSG)", "date": "2026-08-20", "kSum": "글로벌 컨테이너 운임지수가 3주 연속 상승하며 6주 만에 3300선을 회복했다. 상하이해운거래소에 따르면 8월14일자 상하이컨테이너운임지수(SCFI)는 3355.24로 전주 대비 2% 올랐으며, 북미와 남미 노선의 강세가 상승을 견인했다.", "eSum": "The global container freight index rose for a third straight week to reclaim the 3,300 mark for the first time in six weeks. Per the Shanghai Shipping Exchange, the Aug 14 SCFI stood at 3,355.24, up 2% week-on-week, driven by strength on North and South America routes.", "kImp": "미주 노선 수요 회복이 운임 반등을 주도하고 있어 하반기 컨테이너 시황 개선 기대를 뒷받침한다.", "eImp": "Recovering demand on the Americas routes is leading the rate rebound, supporting hopes for improved container market conditions in H2.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147867"}, {"code": "KR", "title": "부산항만공사, 을지연습 연계 부산항 비상대응체계 점검", "src": "코리아쉬핑가제트(KSG)", "date": "2026-08-20", "kSum": "부산항만공사(BPA) 송상근 사장이 을지연습 기간인 20일 연합항만협조본부(CSCC)를 방문해 부산항의 비상대응 태세를 점검했다. 국군수송사령관과 유사시 항만 운영 연속성 확보 방안을 논의하고 한·미 장병을 격려했다.", "eSum": "During the Ulchi exercise, Busan Port Authority (BPA) CEO Song Sang-geun visited the Combined Support Coordination Center (CSCC) on the 20th to review Busan Port's emergency-response posture, discussing port operational continuity in contingencies with the ROK transportation commander and encouraging Korean and US troops.", "kImp": "국가 최대 항만의 유사시 운영 연속성 점검으로, 안보 리스크 국면에서 물류 인프라 보호의 중요성을 부각한다.", "eImp": "A continuity review at Korea's largest port highlights the importance of protecting logistics infrastructure amid security risks.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147875"}, {"code": "KR", "title": "HD현대중공업, 페루 상륙지원함 진수…해외 첫 함정 공동건조 성공", "src": "코리아쉬핑가제트(KSG)", "date": "2026-08-20", "kSum": "HD현대중공업(HD Hyundai Heavy Industries)이 페루 시마(SIMA)조선소에서 페루 해군 신형 상륙지원함 1번함 '침보테(Chimbote)함' 진수식을 실시했다. 해외 현지에서 함정을 공동건조해 진수까지 성공한 첫 사례로, 방산·조선 수출 경쟁력을 입증했다.", "eSum": "HD Hyundai Heavy Industries launched the first of the Peruvian Navy's new landing platform ships, 'Chimbote', at Peru's SIMA shipyard. It marks the company's first successful co-production and launch of a naval vessel at an overseas yard, demonstrating its defense and shipbuilding export competitiveness.", "kImp": "국내 조선 빅3의 해외 현지 함정 건조 역량을 확인한 사례로, 방산 수출 확대와 기술 이전 모델의 성공 가능성을 보여준다.", "eImp": "Validates a Korean Big-3 shipbuilder's overseas naval construction capability, showcasing a viable model for defense-export expansion and technology transfer.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147868"}, {"code": "KR", "title": "HMM, 인도-동아프리카 잇는 신규 컨테이너 노선 'GIA' 개설", "src": "코리아쉬핑가제트(KSG)", "date": "2026-08-18", "kSum": "HMM(에이치엠엠)이 인도와 동아프리카를 연결하는 신규 컨테이너 서비스 'GIA(Gulf-India-East Africa)'를 오는 9월 개설한다고 밝혔다. 이는 HMM의 두 번째 아프리카 피더 네트워크로, 허브 앤 스포크(Hub & Spoke) 전략에 따라 운영된다.", "eSum": "HMM announced it will launch the new Gulf-India-East Africa (GIA) container service in September, connecting India and East Africa. It is HMM's second African feeder network, operated under its Hub & Spoke strategy.", "kImp": "신흥 시장 네트워크 확장을 통해 노선 포트폴리오를 다변화하려는 전략으로, 아프리카·인도 물동량 성장에 대한 선제 대응으로 평가된다.", "eImp": "A network-expansion move into emerging markets that diversifies HMM's route portfolio and pre-positions it for growing Africa-India trade volumes.", "url": "https://www.ksg.co.kr/news/main_newsView.jsp?pNum=147852"}]}, {"code": "INS", "type": "news", "kTitle": "Section 12. 해상보험 (H&M)", "eTitle": "Section 12. Marine Insurance (H&M)", "items": [{"code": "INS", "title": "호르무즈 해협 통항 지속 둔화…선주들 전쟁위험 우려로 통과 회피", "src": "Insurance Marine News", "date": "2026-08-20", "kSum": "호르무즈 해협(Strait of Hormuz) 통항이 8월18일에도 다시 둔화됐다. 지정학적 불안으로 대부분의 선주가 통과를 보류하고 있으며, 카플러(Kpler) 집계상 통항 선박 수가 크게 줄었다. 전쟁위험(war risk) 보험료 급등과 안전 우려가 겹치며 통항 기피가 이어지고 있다.", "eSum": "Traffic through the Strait of Hormuz slowed again on Aug 18, with most owners holding back from transits amid geopolitical unease; Kpler reported sharply fewer transits. Surging war-risk premiums combined with safety fears are driving continued avoidance.", "kImp": "전쟁위험 요율 상승과 실제 통항 감소가 동반되며, H&M·전쟁위험 인수 시장의 중동 익스포저 관리가 핵심 이슈로 부상했다.", "eImp": "With war-risk rates rising alongside falling transits, managing Middle East exposure has become a central issue for the H&M and war-risk underwriting market.", "url": "https://insurancemarinenews.com/insurance-marine-news/hormuz-traffic-continues-to-slow/"}, {"code": "INS", "title": "흑해서 벌크선 2척 피격 보고…전쟁위험 손해 우려 확대", "src": "Insurance Marine News", "date": "2026-08-19", "kSum": "8월17일 흑해(Black Sea)에서 벌크선 2척(Anna S, IMO 9207778 / Elina B, IMO 9577446)이 피격됐다는 보고가 나왔다. 그리스 언론이 전한 이번 사건은 흑해 항로의 선체·화물 전쟁위험 손해 가능성을 다시 부각시켰다.", "eSum": "Two bulk carriers (Anna S, IMO 9207778; Elina B, IMO 9577446) were reported struck in the Black Sea on Aug 17, according to Greek media. The incident again highlights potential hull and cargo war-risk losses on Black Sea routes.", "kImp": "흑해 상선 피격이 반복되면서 러시아·우크라이나 인근 수역의 전쟁위험 담보 요율과 인수 여력에 추가 압력이 예상된다.", "eImp": "Repeated attacks on merchant ships in the Black Sea point to added pressure on war-risk rates and underwriting capacity for waters near Russia and Ukraine.", "url": "https://insurancemarinenews.com/insurance-marine-news/two-bulk-carriers-reported-as-attacked-in-black-sea/"}, {"code": "INS", "title": "호르무즈 공격으로 선원 사망…이란, 벌크선 'Minoan Dignity' 타격", "src": "Insurance Marine News", "date": "2026-08-19", "kSum": "호르무즈 해협에서 이란의 상선 공격으로 선원 1명이 사망했다. 벌크선 '미노안 디그니티(Minoan Dignity, IMO 9294484)'가 피격된 이번 사건은 중동 항로 상선에 대한 실제 인명 피해로, 전쟁위험 담보와 선원 관련 클레임 리스크를 한층 키웠다.", "eSum": "A seafarer died following Iran's latest attack on merchant shipping in the Strait of Hormuz, when bulk carrier Minoan Dignity (IMO 9294484) was struck. The fatality on a Middle East route intensifies war-risk cover and crew-related claims exposure.", "kImp": "실제 인명 손실 발생으로 중동 전쟁위험이 이론적 리스크를 넘어 현실화됐음을 보여주며, 보험료 경직성과 통항 기피가 강화될 전망이다.", "eImp": "An actual fatality shows Middle East war risk has moved from theoretical to realized, reinforcing premium stickiness and transit avoidance.", "url": "https://insurancemarinenews.com/insurance-marine-news/seafarer-dies-in-soh-strike/"}, {"code": "INS", "title": "이란, UAE 연계 유조선 억류 주장…케슘섬 인근", "src": "Insurance Marine News", "date": "2026-08-19", "kSum": "이란 관영 매체가 UAE(아랍에미리트)와 연계된 유조선 1척을 케슘(Qeshm)섬 인근에서 억류했다고 주장했다. 파르스(Fars) 통신은 선박명·선주·억류 사유를 특정하지 않았으나, 걸프 해역의 선박 억류 리스크를 재확인시켰다.", "eSum": "Iranian state-linked media claimed a UAE-linked tanker was detained near Qeshm Island. Fars News Agency did not identify the vessel, owner or grounds for the detention, but the claim reaffirms vessel-detention risk in the Gulf.", "kImp": "선박 억류는 전쟁위험뿐 아니라 지연·손해방지 비용, 화물 클레임으로 이어질 수 있어 걸프 통항 익스포저 관리 필요성을 키운다.", "eImp": "Detentions can trigger not just war-risk but delay, sue-and-labour costs and cargo claims, raising the need to manage Gulf transit exposure.", "url": "https://insurancemarinenews.com/insurance-marine-news/iran-says-it-has-detained-a-uae-linked-tanker/"}, {"code": "INS", "title": "제재대상 유조선 'Caroline Bezengi' 유출유 오만 해안 상륙", "src": "Insurance Marine News", "date": "2026-08-20", "kSum": "좌초한 제재대상 유조선 '캐롤라인 베젠기(Caroline Bezengi)'에서 유출된 기름이 오만(Oman) 본토 해안에 상륙하기 시작했다. 오만 당국이 방제 작업에 총력을 기울이고 있으며, 오염 손해와 잔존물 처리 관련 비용 부담이 커지고 있다.", "eSum": "Oil spilled from the grounded, sanctioned tanker Caroline Bezengi has begun washing ashore on mainland Oman, with authorities scrambling to clean it up. Pollution damage and wreck/residue-handling costs are mounting.", "kImp": "제재선박의 좌초·오염 사고는 보상 주체가 불분명해 연안국·보험시장의 손해 부담과 법적 분쟁 가능성을 키운다.", "eImp": "Grounding and pollution from a sanctioned vessel leave liability unclear, increasing loss burden on coastal states and the insurance market and the risk of legal disputes.", "url": "https://insurancemarinenews.com/insurance-marine-news/oman-working-hard-to-clean-up-oil-as-spill-from-caroline-bezengi-hits-land/"}, {"code": "INS", "title": "마르코 캐피탈, 프로 글로벌 인수 합의…보험 레거시 시장 재편", "src": "Insurance Marine News", "date": "2026-08-20", "kSum": "손해보험 레거시(legacy) 통합업체이자 폴로웍스(PoloWorks)의 모회사인 마르코 캐피탈(Marco Capital)이 보험 서비스 그룹 프로 글로벌(Pro Global) 인수에 합의했다. 규제 승인 등을 조건으로 하며, 마린 인접 보험 서비스 시장의 통합 흐름을 보여준다.", "eSum": "Marco Capital, a P&C legacy consolidator and parent of PoloWorks, has agreed to acquire insurance services group Pro Global, subject to conditions including regulatory approval. The deal reflects consolidation in the marine-adjacent insurance services market.", "kImp": "레거시·서비스 부문의 통합은 마린 보험 밸류체인의 운영 효율화와 클레임 처리 역량 재편으로 이어질 수 있다.", "eImp": "Consolidation in the legacy and services segment could reshape operational efficiency and claims-handling capacity across the marine insurance value chain.", "url": "https://insurancemarinenews.com/insurance-marine-news/marco-capital-to-acquire-pro-global/"}, {"code": "INS", "title": "소말리아 앞바다서 일반화물선 'Lutuf' 피랍", "src": "Insurance Marine News", "date": "2026-08-19", "kSum": "8월17일 소말리아 마리요(Mareeyo) 앞바다 약 4해리 지점에서 일반화물선 '루투프(Lutuf, IMO 9109134)'가 무장한 8명에 의해 피랍됐다고 보고됐다. 서인도양의 해적 위험이 다시 부각되며 전쟁·해적위험 담보에 대한 경각심이 커지고 있다.", "eSum": "General cargo ship Lutuf (IMO 9109134) was reported hijacked on Aug 17 by eight armed men about 4nm off Mareeyo, Somalia. The renewed piracy threat in the western Indian Ocean is heightening attention to war/piracy-risk cover.", "kImp": "소말리아 해적 활동 재개 조짐은 인도양 항로의 추가 전쟁·해적위험 요율과 무장경비 수요 증가로 이어질 수 있다.", "eImp": "Signs of resurgent Somali piracy could drive additional war/piracy premiums and demand for armed guards on Indian Ocean routes.", "url": "https://insurancemarinenews.com/insurance-marine-news/vessel-hijacked-off-somali-coast/"}, {"code": "INS", "title": "선원 영상서 '호르무즈 통항 압박' 우려 제기…인도 선원노조 성명", "src": "Insurance Marine News", "date": "2026-08-20", "kSum": "인도전방선원노조(FSUI)가 다목적 해양지원선 'AM Pioneer(IMO 9331323)'에 승선한 인도 선원 16명이 호르무즈 해협 통항을 압박받는 상황에 대해 우려를 표명했다. 위험수역 통항 관련 선원 안전과 고용주 책임 문제가 부각됐다.", "eSum": "The Forward Seamen's Union of India (FSUI) voiced concern over 16 Indian crew aboard the multi-purpose offshore supply vessel AM Pioneer (IMO 9331323) reportedly being pressured to transit the Strait of Hormuz. It raises crew-safety and employer-liability questions around high-risk-area transits.", "kImp": "위험수역 강제 통항 논란은 선원 인권·안전 이슈와 함께 전쟁위험 하에서의 고용주 배상책임(리스크) 문제를 촉발한다.", "eImp": "Disputes over forced high-risk transits raise seafarer-safety concerns and employer-liability exposure under war-risk conditions.", "url": "https://insurancemarinenews.com/insurance-marine-news/concern-raised-in-crew-video-about-pressure-to-transit-soh/"}, {"code": "INS", "title": "마린 라운드업(8월20일)…차나칼레 해협서 화물선 조업불능 등", "src": "Insurance Marine News", "date": "2026-08-20", "kSum": "탄자니아 선적 화물선 '카피탄 시랴긴(Kapitan Shyriagin, IMO 9137234)'이 8월18일 차나칼레(Canakkale) 해협에서 조업불능 상태에 빠졌다. 인명 피해나 오염은 보고되지 않았으며, 이 밖에 여러 해상 사고·손해 동향이 라운드업으로 정리됐다.", "eSum": "Tanzania-flagged cargo vessel Kapitan Shyriagin (IMO 9137234) became disabled in the Canakkale Strait on Aug 18, with no injuries or pollution reported. The round-up also compiled several other casualty and loss developments.", "kImp": "주요 해협에서의 기관 고장·조업불능 사고는 예인·구조·화물 지연 등 복합 클레임으로 확대될 수 있어 선체보험 손해 모니터링이 필요하다.", "eImp": "Breakdowns in key straits can escalate into towage, salvage and cargo-delay claims, warranting close hull-loss monitoring.", "url": "https://insurancemarinenews.com/insurance-marine-news/marine-round-up-20th-august-2026/"}]}, {"code": "PNI", "type": "news", "kTitle": "Section 13. P&I 클럽", "eTitle": "Section 13. P&I Clubs", "items": [{"code": "PNI", "title": "UK P&I, 2026 PSC 집중점검(CIC) '화물 고박' 대비 핵심 고려사항 안내", "src": "UK P&I Club", "date": "2026-08-19", "kSum": "UK P&I 클럽(UK P&I Club)이 2026년 항만국통제(PSC) 집중점검(CIC) 주제인 '화물 고박(Cargo Securing)'과 관련해 선박 운항자를 위한 핵심 고려사항을 안내했다. 고박 매뉴얼 준수, 고박장비 점검, 기록 관리 등 결함 지적을 예방하기 위한 실무 대응 방안을 제시했다.", "eSum": "The UK P&I Club issued key considerations for ship operators ahead of the 2026 PSC Concentrated Inspection Campaign (CIC) on Cargo Securing, covering compliance with the cargo securing manual, inspection of securing equipment and record-keeping to avoid deficiencies and detentions.", "kImp": "PSC CIC는 결함·억류로 이어질 수 있어 사전 대비가 중요하며, 클럽의 실무 가이드는 회원사의 억류·클레임 리스크 저감에 직접 기여한다.", "eImp": "PSC CICs can lead to deficiencies and detentions; the club's practical guidance directly helps members reduce detention and claims risk.", "url": "https://www.ukpandi.com/news-and-resources/news/article/2026-psc-cic-on-cargo-securing-key-considerations-for-ship-operators/"}, {"code": "PNI", "title": "노스스탠다드(NorthStandard), 모잠비크 베이라항 접안 지연 회원 안내", "src": "Insurance Marine News / NorthStandard", "date": "2026-08-20", "kSum": "영국 기반 P&I 클럽 노스스탠다드(NorthStandard)가 모잠비크 베이라(Beira)항에서 화물을 취급하는 선박들의 접안 지연이 지속되고 있다고 회원사에 안내했다. 항만 혼잡에 따른 대기 시간 증가와 이에 수반되는 체선·비용 리스크에 대한 주의를 당부했다.", "eSum": "UK-based Group Club NorthStandard advised members of continuing berthing delays at Beira, Mozambique, for vessels trading there, flagging longer waiting times from port congestion and the associated demurrage and cost risks.", "kImp": "항만 지연은 체선료·계약 분쟁·화물 손상 클레임으로 확대될 수 있어, 클럽의 사전 경보는 회원사의 운항계획 조정에 유용하다.", "eImp": "Port delays can escalate into demurrage, contractual disputes and cargo-damage claims, so the club's early warning aids members' voyage planning.", "url": "https://insurancemarinenews.com/insurance-marine-news/berthing-delays-in-mozambique-port/"}, {"code": "PNI", "title": "웨스트 P&I, 쿠바 인도적 교역 관련 OFAC 명확화 회원 안내", "src": "Insurance Marine News / West P&I Club", "date": "2026-08-20", "kSum": "웨스트 P&I 클럽(West P&I Club)이 미국 OFAC(해외자산통제국)의 쿠바 인도적 물품 교역 관련 명확화 내용을 회원사에 안내했다. 인도적 부문에서 누가, 무엇을 거래할 수 있는지에 대한 미국의 해석을 정리해 제재 준수 리스크를 낮추는 데 목적이 있다.", "eSum": "West P&I Club informed members of a US clarification (OFAC) on humanitarian trade with Cuba, setting out who may trade and what may be traded in the humanitarian products sector to help members manage sanctions-compliance risk.", "kImp": "제재 해석의 명확화는 회원사의 인도적 교역 관련 계약 이행과 담보 유지에 직결되며, 제재 위반에 따른 담보 상실 리스크를 줄인다.", "eImp": "Clarified sanctions interpretation bears directly on members' ability to perform humanitarian-trade contracts and maintain cover, reducing the risk of losing cover for breaches.", "url": "https://insurancemarinenews.com/insurance-marine-news/ofac-clarifies-humanitarian-trade-conditions-with-cuba/"}]}, {"code": "VET", "type": "news", "kTitle": "Section 14. 베팅·검사", "eTitle": "Section 14. Vetting & Inspection", "items": [{"code": "VET", "title": "'선박을 넘어서' — 베팅은 쌍방향 책임이다 (Prevention at Sea)", "src": "MaritimeCyprus", "date": "2026-08-16", "kSum": "Prevention at Sea의 Daniele Badalucco 최고HSQE책임자가 베팅(vetting)은 선박 운항자만의 책임이 아니라 용선주·터미널·선급·조선소 등 전체 사슬의 쌍방향 책임이라고 주장했다. 탱커 pre-SIRE 2.0 점검에서 안전관리(Safety Management)가 지적의 44.7%, 항해·통신이 26.8%를 차지했고, 10개 분기 동안 ECDIS 관련 지적은 24%→8%로 감소한 반면 선교 주의분산(distraction) 지적은 4%→15%로 증가했다.", "eSum": "Capt. Daniele Badalucco (Chief HSQE Officer, Prevention at Sea) argues vetting is a two-way responsibility shared across charterers, terminals, class and shipbuilders, not the operator alone. In tanker pre-SIRE 2.0 inspections, Safety Management accounted for 44.7% of observations and Navigation/Communication 26.8%; over ten quarters ECDIS findings fell 24%→8% while bridge-distraction findings rose 4%→15%.", "kImp": "RISQ·SIRE 2.0가 인적요소·행동 평가로 이동함에 따라 관리선사는 절차뿐 아니라 선교 주의분산 등 행동 리스크를 관리해야 하며, 용선주·터미널의 역할도 부각된다.", "eImp": "As RISQ/SIRE 2.0 shift toward human-factor and behaviour assessment, managers must address behavioural risks such as bridge distraction, with charterers and terminals also sharing responsibility.", "url": "https://maritimecyprus.com/2026/08/16/beyond-the-ship-why-vetting-is-a-two-way-street/"}]}, {"code": "CLASS", "type": "news", "kTitle": "Section 15. 선급", "eTitle": "Section 15. Classification Societies", "items": [{"code": "CLASS", "title": "ClassNK joins project to verify GHG emission reduction through AI-based voyage optimization on an actual vessel (MOU with Evergreen, Samsung Heavy Industries, Weathernews)", "src": "ClassNK", "date": "2026-08-20", "kSum": "ClassNK(일본선급)가 에버그린(Evergreen Marine·長榮海運), 삼성중공업(Samsung Heavy Industries), 웨더뉴스(Weathernews)와 MOU를 체결하여 실제 운항 선박에서 AI 기반 항해최적화 기술의 GHG(온실가스) 배출 저감 효과를 검증하기로 했다. 선급은 연료절감·배출저감 실증 결과에 대한 기술 검증을 제공한다.", "eSum": "ClassNK signed an MOU with Evergreen Marine, Samsung Heavy Industries and Weathernews to jointly verify, on an in-service vessel, how much GHG emissions can be cut using AI-based voyage optimization technology, with the class society providing technical verification of the results.", "kImp": "AI 항해최적화의 실선 검증은 선주가 IMO 및 FuelEU 탈탄소 규제 대응에 활용할 수 있는 선급 공인 근거를 제공한다.", "eImp": "Actual-vessel validation of AI voyage optimization gives owners class-backed evidence they can use toward IMO and FuelEU decarbonization compliance.", "url": "https://www.classnk.or.jp/hp/en/news.aspx?id=15482&layout=1&type=p"}, {"code": "CLASS", "title": "Design choices 'make or break' subsea pipeline integrity, finds LR study for Havtil", "src": "Lloyd's Register", "date": "2026-08-20", "kSum": "로이드선급(Lloyd's Register)이 노르웨이 규제당국 Havtil을 위해 수행한 기술 연구에서 초기 설계 단계의 선택이 해저 파이프라인의 장기 건전성(부식·피로·수명)을 좌우한다는 결과를 발표했다.", "eSum": "Lloyd's Register published a technical study for Norwegian regulator Havtil finding that early design choices are decisive for the long-term integrity of subsea pipelines, influencing corrosion, fatigue and lifetime reliability.", "kImp": "이 연구 결과는 운영사와 규제당국에 해저 파이프라인 고장 위험을 줄이기 위한 선급 공인 지침을 제공한다.", "eImp": "The findings give operators and regulators class-backed guidance to reduce subsea pipeline failure risk in offshore gas and energy infrastructure.", "url": "https://www.lr.org/en/knowledge/press-room/press-listing/press-release/2026/design-choices-make-or-break-subsea-pipeline-integrity-finds-lr-study-for-havtil/"}, {"code": "CLASS", "title": "LR supports LNG carrier-to-FSU conversion for Perenco offshore gas project", "src": "Lloyd's Register", "date": "2026-08-19", "kSum": "로이드선급(Lloyd's Register)이 페렌코(Perenco) 계열사의 프로젝트를 위해 구 LNG선 'LNG Bayelsa'를 부유식 저장설비(FSU 'LNG Cap Lopez')로 개조하는 작업에 선급·도면승인·검사·기술보증을 제공한다. 개조 FSU는 가봉 해상 Cap Lopez 가스전용 LNG를 저장한다.", "eSum": "Lloyd's Register is providing classification, plan approval, survey and technical assurance for converting the former LNG carrier LNG Bayelsa (renamed FSU LNG Cap Lopez) into a floating storage unit at Drydocks World Dubai for a Perenco sister company, serving Gabon's offshore Cap Lopez gas project.", "kImp": "선급 주도의 선박 수명연장·개조가 신조선 대비 빠르고 저렴한 대안임을 보여주며, 부유식 가스 인프라 수요 증가에 대응한다.", "eImp": "The project shows classification-led life-extension and conversion offering a faster, lower-cost alternative to newbuilds as demand for floating gas infrastructure grows.", "url": "https://www.lr.org/en/knowledge/press-room/press-listing/press-release/2026/lloyds-register-supports-lng-carrier-to-fsu-conversion-for-perenco-offshore-gas-project/"}]}, {"code": "COMM", "type": "news", "kTitle": "Section 16. 상업·용선시장", "eTitle": "Section 16. Commercial & Chartering", "items": [{"code": "COMM", "title": "Transpacific Container Rates Surge as Carriers Cut Capacity", "src": "gCaptain", "date": "2026-08-20", "kSum": "드류리(Drewry) 세계컨테이너지수(WCI)가 2주 연속 상승해 40피트 컨테이너당 4,526달러로 4% 올랐다. 상하이~뉴욕 운임은 9% 급등한 9,507달러, 상하이~로스앤젤레스는 9% 오른 6,802달러를 기록했다. 선사들이 결항(blank sailing)과 공급 축소로 태평양항로 선복을 조이면서 아시아~미동안 선복은 전월 대비 9% 감소했고, 여러 선사가 9월부터 아시아~미동안·걸프 노선에 파나마운하 할증료를 예고했다. 반면 아시아~유럽 운임은 소폭 하락했다.", "eSum": "Drewry's WCI rose 4% for a second straight week to $4,526 per 40ft as Transpacific rates jumped, with Shanghai-New York up 9% to $9,507 and Shanghai-LA up 9% to $6,802. Carriers tightened Pacific capacity via blank sailings, cutting Asia-US East Coast capacity 9% MoM, and flagged September Panama Canal surcharges, while Asia-Europe rates softened.", "kImp": "지정학·항만혼잡·선사 공급조절이 겹치며 태평양 운임 강세가 이어져 화주 물류비 부담과 성수기 롤오버 위험이 커지고 있다.", "eImp": "Geopolitics, port congestion and disciplined capacity management are sustaining Transpacific rate strength, raising shipper costs and peak-season rollover risk.", "url": "https://gcaptain.com/transpacific-container-rates-surge-as-carriers-cut-capacity/"}, {"code": "COMM", "title": "Drewry WCI rises for second week as Transpacific rates climb", "src": "Container News", "date": "2026-08-15", "kSum": "드류리 WCI가 8월 13일 기준 1% 오른 40피트당 4,339달러로 2주 연속 상승했다. 상하이~뉴욕이 10% 급등한 8,706달러로 8대 동서항로 중 최대 상승폭을 보였고, 상하이~로스앤젤레스도 6% 오른 6,244달러였다. 선사들은 최근 2주간 주당 10건씩 결항했다. 반면 아시아~유럽은 하락해 상하이~제노바 -8%(5,080달러), 상하이~로테르담 -5%(4,425달러)를 기록했다. 수에즈·호르무즈 안보, 파나마운하 제약, 태풍 돌핀발 아시아 항만혼잡이 변동성을 키웠다.", "eSum": "Drewry's WCI rose 1% to $4,339 per 40ft on 13 August, its second weekly gain, led by Shanghai-New York up 10% to $8,706 and Shanghai-LA up 6% to $6,244, as carriers blanked 10 sailings weekly. Asia-Europe eased (Shanghai-Genoa -8%, Shanghai-Rotterdam -5%). Suez/Hormuz security, Panama limits and Typhoon Dolphin congestion added volatility.", "kImp": "동서항로 운임이 지정학·기상·운하 제약 속에 방향성이 갈리며, 선사의 공급조절과 할증료가 운임을 떠받치는 구조가 지속된다.", "eImp": "East-West rates are diverging amid geopolitical, weather and canal disruptions, with capacity control and surcharges underpinning freight levels.", "url": "https://container-news.com/drewry-wci-rises-for-second-week-as-transpacific-rates-climb/"}, {"code": "COMM", "title": "Trump delays 50% Canada tariffs as trade talks advance", "src": "Container News", "date": "2026-08-20", "kSum": "미국 트럼프 대통령이 1930년 관세법 338조에 근거한 캐나다산 일부 품목(주류·유제품·자동차)에 대한 50% 추가관세 발효를 8월 19일에서 8월 22일로 3일 연기했다. 백악관은 캐나다와의 무역협상 진전을 이유로 들었다. 해당 관세는 약 200억달러 규모 캐나다 상품에 영향을 미치며, 자동차 관세를 25%에서 15%로 낮추는 방안과 철강·알루미늄 관세(50%→25%) 조정도 협상 중이다.", "eSum": "President Trump delayed 50% Section 338 tariffs on certain Canadian goods (alcohol, dairy, vehicles) from 19 to 22 August, citing progress in US-Canada trade talks. The duties cover ~$20bn of goods; negotiations also cover cutting auto tariffs from 25% to 15% and steel/aluminium from 50% to 25%.", "kImp": "북미 무역 마찰의 향방은 컨테이너 물동량과 공급망 비용에 직접 영향을 미쳐, 관세 연기는 단기 불확실성 완화 신호로 해석된다.", "eImp": "The trajectory of North American trade friction directly affects container volumes and supply-chain costs; the delay eases near-term uncertainty.", "url": "https://container-news.com/trump-delays-50-canada-tariffs-as-trade-talks-advance/"}, {"code": "COMM", "title": "Hapag-Lloyd's Zim Takeover Hits Regulatory Headwinds", "src": "gCaptain", "date": "2026-08-19", "kSum": "하파크로이트(Hapag-Lloyd)의 짐(ZIM) 인수 계획이 규제·정치적 반발에 부딪혔다. 포워더들이 브라질 당국과 이스라엘 의원들의 이의 제기에 동조하며 정기선 추가 통합에 대한 우려를 제기했다. 반대 측은 해당 인수가 시장 집중을 심화시켜 화주 선택권과 경쟁을 약화시킬 수 있다고 지적한다.", "eSum": "Hapag-Lloyd's planned acquisition of ZIM is facing regulatory and political pushback, with freight forwarders backing objections from Brazilian authorities and Israeli legislators over further liner consolidation and its impact on competition.", "kImp": "대형 정기선 M&A는 항로 경쟁구도와 운임 협상력을 바꿔 화주와 규제당국의 관심이 집중되며, 통합 심화에 대한 견제가 커지고 있다.", "eImp": "Major liner M&A reshapes route competition and pricing power, drawing scrutiny from shippers and regulators wary of deepening consolidation.", "url": "https://gcaptain.com/hapag-lloyds-zim-takeover-hits-regulatory-headwinds/"}, {"code": "COMM", "title": "Evalend reloads at Yangzijiang with $220m LR1 quartet", "src": "Splash247", "date": "2026-08-20", "kSum": "그리스 선주 에발렌드 시핑(Evalend Shipping)이 중국 양쯔장조선(Yangzijiang Shipbuilding)에 LR1 프로덕트 탱커 4척을 약 2억2,000만달러에 발주하며 신조 프로그램을 재가동했다. 프로덕트 탱커 부문 선복 확충 흐름을 반영한 계약으로, 견조한 탱커 시황 속에 그리스 선주의 아시아 조선소 발주가 이어지고 있다.", "eSum": "Greek owner Evalend Shipping returned to the newbuilding market with an order for four LR1 product tankers at China's Yangzijiang Shipbuilding worth about $220m, reflecting continued fleet expansion in the product-tanker segment amid firm tanker markets.", "kImp": "프로덕트 탱커 신조 발주 지속은 정제품 물류 재편과 탱커 선복 수급 전망에 영향을 주며, 아시아 조선소의 수주 잔량을 두텁게 한다.", "eImp": "Ongoing product-tanker ordering signals shifting refined-product trade flows and supports tanker supply outlook, thickening Asian yards' orderbooks.", "url": "https://splash247.com/evalend-reloads-at-yangzijiang-with-220m-lr1-quartet/"}, {"code": "COMM", "title": "Hutchison lines up $76m Karachi terminal upgrade", "src": "Splash247", "date": "2026-08-20", "kSum": "허치슨 포트(Hutchison Ports)가 파키스탄 카라치(Karachi) 컨테이너 터미널 현대화에 7,600만달러를 투자하기로 했다. 장비·인프라 업그레이드를 통해 처리능력과 효율을 높이려는 계획으로, 남아시아 관문 항만의 경쟁력 강화와 물동량 확대를 겨냥한 투자다.", "eSum": "Hutchison Ports lined up a $76m upgrade of its Karachi container terminal in Pakistan, investing in equipment and infrastructure to boost handling capacity and efficiency at a key South Asian gateway.", "kImp": "관문 항만 투자는 지역 물동량 성장과 공급망 안정성에 기여하며, 항만 운영사의 신흥시장 확장 전략을 보여준다.", "eImp": "Gateway-port investment supports regional volume growth and supply-chain resilience, illustrating operators' expansion into emerging markets.", "url": "https://splash247.com/hutchison-lines-up-76m-karachi-terminal-upgrade/"}, {"code": "COMM", "title": "Kamarajar Port opens bidding for 2m teu second container terminal", "src": "Splash247", "date": "2026-08-21", "kSum": "인도 카마라자르 항(Kamarajar Port)이 연간 200만 TEU 처리능력의 제2 컨테이너 터미널 개발 입찰을 개시했다. 인도 동안의 컨테이너 처리 수요 증가에 대응한 항만 확충 계획으로, 민간 참여를 통한 대규모 인프라 투자를 유치하려는 움직임이다.", "eSum": "India's Kamarajar Port opened bidding for a second container terminal with capacity of 2m teu, expanding east-coast box-handling capacity to meet rising demand and attract private investment in large-scale port infrastructure.", "kImp": "인도의 컨테이너 항만 증설은 남아시아 물류 허브 경쟁과 아시아 역내 물동량 성장 전망에 긍정적 신호를 준다.", "eImp": "India's container capacity expansion signals intensifying South Asian hub competition and a positive outlook for intra-Asian volume growth.", "url": "https://splash247.com/kamarajar-port-opens-bidding-for-2m-teu-second-container-terminal/"}]}, {"code": "GEO", "type": "news", "kTitle": "Section 17. 지정학", "eTitle": "Section 17. Geopolitics", "items": [{"code": "GEO", "title": "Russia and Ukraine Continue Targeting Shipping with Claims of Nine Strikes", "src": "The Maritime Executive", "date": "2026-08-19", "kSum": "러시아와 우크라이나의 상선 공격이 격화돼 24시간 새 최소 9척이 피격됐다고 보도됐다. 우크라이나는 노보로시스크(Novorossiysk) 인근에서 벌크선 최대 5척을 타격했고, 러시아 국방부는 최소 4척 공격을 주장했다. 미국과 튀르키예가 흑해 상선 공격 중단을 위한 모라토리엄을 제안했으나 러시아는 이를 거부했다. 그리스 소유 벌크선 안나 S(Anna S)는 드론 공격으로 화재가 발생해 선원들이 퇴선했다.", "eSum": "Attacks on commercial shipping intensified, with reports of nine vessels hit in 24 hours. Ukraine struck up to five bulkers near Novorossiysk while Russia claimed at least four. A US- and Turkey-backed moratorium proposal was rejected by Moscow. The Greek-owned bulker Anna S caught fire after drone strikes, forcing her crew to abandon ship.", "kImp": "흑해 상선 공격의 상호 격화는 곡물 수출과 선원 안전을 위협하고 전쟁위험 보험료를 끌어올려 세계 식량·에너지 공급망에 파장을 준다.", "eImp": "Escalating mutual attacks threaten grain exports and seafarer safety, drive up war-risk premiums, and ripple through global food and energy supply chains.", "url": "https://maritime-executive.com/article/russia-and-ukraine-continue-targeting-shipping-with-claims-of-nine-strikes"}, {"code": "GEO", "title": "At least five vessels carrying grain attacked in Novorossiysk and Tuapse", "src": "SAFETY4SEA", "date": "2026-08-19", "kSum": "8월 17~18일 러시아 흑해 항만 노보로시스크와 투압세(Tuapse) 인근에서 최소 5척의 곡물운반선이 드론 공격을 받았다. 라이베리아 선적·그리스 소유 안나 S가 드론 5기에 피격돼 거의 완파됐고, UAE 관리 페후(Fehu), 러시아 선적 빅토리아 V(Victoria V), 튀르키예 선박 네시베(Necibe) 등이 피해를 입었다. 곡물 적재 또는 적재를 위해 입항하던 선박들이 표적이 됐다.", "eSum": "At least five grain carriers were hit by drones near the Russian Black Sea ports of Novorossiysk and Tuapse on 17-18 August. The Liberia-flagged, Greek-owned Anna S was nearly destroyed after five drone strikes; the UAE-managed Fehu, Russian-flagged Victoria V and Turkish vessel Necibe were also damaged while loading or approaching to load grain.", "kImp": "곡물 수출 관문에 대한 집중 공격은 흑해 곡물 물류를 마비시켜 국제 밀 가격 상승과 중동·아프리카·아시아 수입국 리스크를 키운다.", "eImp": "Concentrated strikes on grain gateways paralyse Black Sea grain logistics, pushing up wheat prices and raising risk for importers in the Middle East, Africa and Asia.", "url": "https://safety4sea.com/at-least-five-vessels-carrying-grain-attacked-in-novorossiysk-and-tuapse/"}, {"code": "GEO", "title": "Second IMS tanker hit in Black Sea drone campaign", "src": "Splash247", "date": "2026-08-17", "kSum": "그리스 탱커 선주 IMS의 수에즈막스 스키로스(Skiros)가 노보로시스크 앞바다에서 원유 적재 중 드론에 선교(bridge)를 피격당해 화재가 발생했다. 라이베리아 선적 15만9,021DWT 선박으로 카스피 파이프라인 컨소시엄(CPC) 터미널로 향하던 중이었다. 이는 이달 초 IMS의 또 다른 탱커 부르다(Bourda) 피격에 이은 두 번째 공격으로, 우크라이나가 비러시아 탱커·CPC 인프라 공격 중단에 합의한 미국 중재 이후여서 주목된다.", "eSum": "IMS's suezmax Skiros was struck on the bridge by a drone while loading oil off Novorossiysk, sparking a fire. The 159,021 dwt Liberia-flagged tanker was bound for the CPC terminal. It was the second hit on an IMS tanker this month after the Bourda, drawing attention because it followed a US-brokered understanding for Ukraine to halt strikes on non-Russian tankers and CPC infrastructure.", "kImp": "CPC 연계 탱커 피격은 미국 중재 합의의 취약성을 드러내며, 흑해 원유 수출과 카자흐스탄 경유 물류의 불확실성을 키운다.", "eImp": "The strike on a CPC-linked tanker exposes the fragility of the US-brokered understanding, raising uncertainty over Black Sea crude exports and Kazakh transit flows.", "url": "https://splash247.com/second-ims-tanker-hit-in-black-sea-drone-campaign/"}, {"code": "GEO", "title": "Russia and Ukraine's Black Sea Grain Exports Grind to a Virtual Halt", "src": "gCaptain", "date": "2026-08-19", "kSum": "상선 공격으로 러시아·우크라이나의 아조프·흑해 곡물 수출능력 97% 이상이 마비됐다고 로이터가 전했다. 우크라이나 흑해 터미널의 선적은 사실상 중단됐고, 러시아에서 공식 가동 중인 곡물 터미널은 투압세의 소규모 시설(월 16만톤)뿐이다. 세계 밀 가격은 이달 약 6.5% 올라 1년 전보다 약 30% 높다. 러시아 8월 밀 수출은 2010년 이후 최저인 180만톤으로 추정된다.", "eSum": "Attacks on shipping have shut more than 97% of Russia and Ukraine's Azov and Black Sea grain export capacity, Reuters reported. Ukraine's Black Sea terminals have no shipments, and Russia's only officially open grain terminal is a small Tuapse facility. Global wheat prices are up ~6.5% this month and ~30% year-on-year; Russia's August wheat exports are seen at 1.8m tons, the lowest for the month since 2010.", "kImp": "세계 최대 곡물 수출지역의 물류 마비는 저가 곡물 공급을 차단해 국제 식량가격을 끌어올리고 수입국들의 대체 조달 부담을 가중시킨다.", "eImp": "Paralysis in a top grain-exporting region cuts off low-cost supply, lifting global food prices and forcing importers toward costlier alternative sources.", "url": "https://gcaptain.com/russia-and-ukraines-black-sea-grain-exports-grind-to-a-virtual-halt/"}, {"code": "GEO", "title": "Black Sea export war intensifies", "src": "Splash247", "date": "2026-08-20", "kSum": "흑해를 둘러싼 러시아·우크라이나의 수출 전쟁이 격화되며 양측이 상대의 항만·터미널·상선을 겨냥한 공격을 확대하고 있다. 곡물과 원유 수출 인프라가 표적이 되면서 흑해 항로의 상업 운항이 위축되고, 선주·용선주·보험사가 리스크 재평가에 나섰다.", "eSum": "The Russia-Ukraine export war in the Black Sea is intensifying, with both sides widening attacks on each other's ports, terminals and merchant ships. As grain and crude export infrastructure is targeted, commercial navigation is contracting and owners, charterers and insurers are re-pricing risk.", "kImp": "흑해 수출 인프라를 둘러싼 소모전 격화는 곡물·에너지 물류의 구조적 불안정을 심화시켜 전쟁위험 보험과 운임에 지속적 상방 압력을 준다.", "eImp": "The intensifying attrition over Black Sea export infrastructure deepens structural instability in grain and energy logistics, sustaining upward pressure on war-risk cover and freight.", "url": "https://splash247.com/black-sea-export-war-intensifies/"}, {"code": "GEO", "title": "Oman Works to Clean Up Spill as Oil From Stricken Tanker Comes Ashore", "src": "The Maritime Executive", "date": "2026-08-18", "kSum": "러시아 그림자함대(shadow fleet) 탱커 캐롤라인 베젠기(Caroline Bezengi)에서 유출된 기름이 오만 본토 해안에 밀려오면서 당국이 약 6~8마일(12km) 구간에서 수작업 방제에 나섰다. 6월 폭발로 무력화돼 좌초한 만재 수에즈막스로, 17도 경사·펑크 난 탱크에서 계속 기름이 새고 있다. 보호 해양구역인 이 지역은 바다거북·혹등고래 서식지로 심각한 환경 위협에 놓였다.", "eSum": "Oil from the Russian shadow-fleet tanker Caroline Bezengi is coming ashore in mainland Oman, prompting a hand cleanup along a 6-8 mile stretch. The fully laden suezmax, disabled by a June explosion and grounded, is listing 17 degrees with punctured tanks still leaking. The protected marine area, home to sea turtles and humpback whales, faces a serious environmental hazard.", "kImp": "그림자함대 노후 탱커의 좌초·유출 사고는 제재 회피 선단이 야기하는 환경·안전 리스크를 부각하며, 국제사회의 단속 강화 명분을 키운다.", "eImp": "The grounding and spill from an ageing shadow-fleet tanker highlight the environmental and safety risks posed by the sanctions-evading fleet, strengthening the case for tougher enforcement.", "url": "https://maritime-executive.com/article/oman-works-to-clean-up-spill-as-oil-from-stricken-tanker-comes-ashore"}, {"code": "GEO", "title": "Cargo Ship Destroyed in New Attack Off Yemen", "src": "gCaptain", "date": "2026-08-18", "kSum": "예멘 앞바다에서 화물선이 정체불명의 발사체에 여러 차례 피격돼 추정전손(constructive total loss) 판정을 받았다. 남부 홍해에서 갈수록 격화되는 공격의 일환으로, 영국 해사기구(UKMTO)가 사건을 확인했다. 홍해·바브엘만데브 항로의 안보 불안이 재점화되며 상선 통항 위험이 다시 높아지고 있다.", "eSum": "A cargo ship off Yemen was declared a constructive total loss after being struck by multiple unknown projectiles, part of increasingly volatile attacks in the southern Red Sea confirmed by UKMTO. Security fears along the Red Sea and Bab el-Mandeb are reigniting, raising transit risk for commercial shipping.", "kImp": "홍해 남부 공격 재개는 수에즈운하 우회와 희망봉 항로 확대를 부추겨 아시아~유럽 물류비와 운항일수를 다시 밀어올린다.", "eImp": "Renewed southern Red Sea attacks encourage Suez diversions and Cape of Good Hope routing, again lifting Asia-Europe costs and voyage times.", "url": "https://gcaptain.com/cargo-ship-destroyed-in-new-attack-off-yemen/"}, {"code": "GEO", "title": "US ends extra security measures on ships calling Nigeria", "src": "Splash247", "date": "2026-08-19", "kSum": "미국이 나이지리아 기항 선박에 부과했던 추가 보안조치를 종료했다. 기니만(Gulf of Guinea) 해적·무장강도 위협 완화에 따른 조치로, 서아프리카 해역의 보안 상황 개선을 반영한다. 해당 조치 해제는 해당 항로를 운항하는 선사의 규제 부담과 운항 비용을 낮추는 효과가 기대된다.", "eSum": "The US ended additional security measures previously required for ships calling at Nigeria, reflecting an easing of piracy and armed-robbery threats in the Gulf of Guinea. Lifting the requirements is expected to reduce compliance burdens and operating costs for carriers serving West Africa.", "kImp": "기니만 보안조치 완화는 서아프리카 해역 위협이 줄었다는 신호로, 해적 리스크 지형 변화와 지역 항로 운항 여건 개선을 시사한다.", "eImp": "Easing Gulf of Guinea measures signals reduced West African threats, pointing to a shifting piracy-risk landscape and improved conditions on regional routes.", "url": "https://splash247.com/us-ends-extra-security-measures-on-ships-calling-nigeria/"}, {"code": "GEO", "title": "South Korea Tests Arctic Shipping Route to Europe", "src": "gCaptain", "date": "2026-08-19", "kSum": "한국이 북극항로(Northern Sea Route)를 통해 유럽으로 향하는 컨테이너선을 시범 운항한다. 해빙으로 열린 항로의 상업성을 검증하려는 시도지만, 러시아의 협조가 필요해 서방 동맹국들과의 마찰 위험을 안고 있다. 수에즈·홍해 불안 속에 대체 항로 모색이 활발해지는 가운데 지정학적 함의가 큰 시험 운항이다.", "eSum": "South Korea is trialling a containership bound for Europe via the Arctic's Northern Sea Route, testing whether the ice-opened passage can be commercially viable. Because the voyage requires Russian cooperation, it risks friction with Western allies, and carries significant geopolitical weight amid Suez and Red Sea instability.", "kImp": "북극항로 상업화 시도는 지정학적 긴장과 대체 항로 경쟁이 얽힌 글로벌 물류 재편의 신호로, 러시아 의존과 서방 관계 사이의 균형이 관건이다.", "eImp": "Testing Arctic commercialisation signals a geopolitically charged reshaping of global logistics, with the balance between Russian dependence and Western ties as the key issue.", "url": "https://gcaptain.com/south-korea-tests-arctic-shipping-route-to-europe/"}]}, {"code": "TW", "type": "news", "kTitle": "Section 18. TradeWinds 선박관리", "eTitle": "Section 18. TradeWinds Ship Management", "items": [{"code": "TW", "title": "Wallenius Wilhelmsen and Seacor arms score US military ro-ro charters", "src": "TradeWinds", "date": "2026-08-18", "kSum": "발레니우스 빌헬름센(Wallenius Wilhelmsen)의 ARC(American Roll-on Roll-Off Carrier)와 시코(Seacor) 계열 워터맨(Waterman)이 미 군용 로로 단기 용선 계약을 확보했다. 미군이 로로선 2척을 약 1,930만 달러 규모로 용선한 것으로 전해진다. (유료기사·헤드라인/스니펫 기준)", "eSum": "TradeWinds reports Wallenius Wilhelmsen's ARC arm and Seacor-linked Waterman Transport secured short-term US military ro-ro charters, with the US military said to have chartered a pair of ro-ros worth about $19.3m. (Paywalled; headline/snippet only.)", "kImp": "정부·군 용선은 자동차운반선 선복에 안정적 일감을 제공하며 미국 국적 로로 운영사의 전략적 역할을 부각한다.", "eImp": "Government/military charters give steady employment to car-carrier tonnage and underline the strategic role of US-flag ro-ro operators.", "url": "https://www.tradewindsnews.com/ship-management/wallenius-wilhelmsen-and-seacor-arms-score-us-military-ro-ro-charters/2-1-2030277"}, {"code": "TW", "title": "Wilh Wilhelmsen banks less profit from car carrier investments", "src": "TradeWinds", "date": "2026-08-14", "kSum": "노르웨이 빌헬름센홀딩(Wilh. Wilhelmsen Holding)이 자동차운반선 투자 기여 감소로 이익이 줄었으나, 지정학적 불확실성에도 향후 실적에 자신감을 보인다고 밝혔다. (유료기사·헤드라인/스니펫 기준)", "eSum": "TradeWinds reports Norway's Wilh Wilhelmsen Holding logged lower earnings as contributions from its car-carrier investments fell, while saying it remains confident of future performance despite geopolitical uncertainty. (Paywalled; headline/snippet only.)", "kImp": "주요 노르웨이 선주·관리사의 PCTC(자동차운반선) 부문 수익성 둔화 신호를 나타낸다.", "eImp": "Signals softening returns from car-carrier/PCTC exposure for a major Norwegian owner-manager amid market uncertainty.", "url": "https://www.tradewindsnews.com/ship-management/wilh-wilhelmsen-banks-less-profit-from-car-carrier-investments/2-1-2029231"}, {"code": "TW", "title": "Brunei shipowner warns global rules could stifle fledgling sector", "src": "TradeWinds", "date": "2026-08-21", "kSum": "브루나이 벨라잇 시핑(Belait Shipping) 회장 겸 브루나이선주협회장이, 현지 사업자의 발전 여건을 고려하지 않은 국제 해사 규제 부과가 브루나이의 신생 선주 부문을 위축시킬 수 있다고 경고했다. (유료기사·헤드라인/스니펫 기준)", "eSum": "TradeWinds reports Belait Shipping's executive chairman, who also heads the Brunei Shipowners Association, warned that imposing international maritime requirements without regard for local operators' development needs could stifle Brunei's fledgling shipowning sector. (Paywalled; headline/snippet only.)", "kImp": "글로벌 규제 표준과 신흥시장 선주의 준수 역량 간 긴장을 부각한다.", "eImp": "Highlights the tension between global regulatory standards and emerging-market owners' capacity to comply.", "url": "https://www.tradewindsnews.com/offshore/brunei-shipowner-warns-global-rules-could-stifle-fledgling-sector/2-1-2030480"}, {"code": "TW", "title": "He bought his old boss' company. Now Evangelos Efstathiou is betting on AI", "src": "TradeWinds", "date": "2026-08-20", "kSum": "옛 고용주의 회사를 인수한 에반겔로스 에프스타티우(Evangelos Efstathiou)가 해운 기술과 투자를 결합해 글로벌 무역 가속과 업계 통합을 노리며 AI에 베팅하고 있다. (유료기사·헤드라인/스니펫 기준)", "eSum": "TradeWinds profiles Evangelos Efstathiou, who bought out his former employer's company and is betting on AI, aiming to accelerate global trade and sector consolidation by marrying maritime technology with investment. (Paywalled; headline/snippet only.)", "kImp": "선주·관리사 사이에서 AI와 통합을 경쟁 수단으로 삼으려는 관심이 커지고 있음을 보여준다.", "eImp": "Reflects growing owner/manager interest in AI and consolidation as competitive levers in shipping.", "url": "https://www.tradewindsnews.com/interviews/he-bought-his-old-boss-company-now-evangelos-efstathiou-is-betting-on-ai/2-1-2029583"}, {"code": "TW", "title": "Video: 'Strait of death' voyage order sparks seafarer revolt", "src": "TradeWinds", "date": "2026-08-20", "kSum": "호르무즈 해협('죽음의 해협') 통항 항해 지시가 선원 반발을 촉발했으며, AM Pioneer호 선장은 해당 요구가 선원의 생명을 위험에 빠뜨린다고 밝혔다. (유료기사·헤드라인/스니펫 기준)", "eSum": "TradeWinds reports that a voyage order to transit the Strait of Hormuz, dubbed the 'strait of death,' sparked a seafarer revolt, with the AM Pioneer's captain saying crews' lives are being put at risk. (Paywalled; headline/snippet only.)", "kImp": "고위험 호르무즈 전쟁지역으로 선박을 배선할 때 선박관리사가 직면하는 선원 안전·동의 문제를 부각한다.", "eImp": "Underscores crew-safety and consent challenges for ship managers routing vessels through the high-risk Hormuz war zone.", "url": "https://www.tradewindsnews.com/people/video-strait-of-death-voyage-order-sparks-seafarer-revolt/2-1-2031675"}]}, {"code": "HOT", "type": "news", "kTitle": "Section 19. 핫이슈: 호르무즈 해협", "eTitle": "Section 19. Hot Topic: Strait of Hormuz", "items": [{"code": "HOT", "title": "Oil Supertanker Earnings on Mideast Route Near $510,000 a Day", "src": "gCaptain", "date": "2026-08-18", "kSum": "페르시아만~중국(중동~아시아) VLCC 수익이 8월 18일 일당 약 51만달러로 6월 말 이후 최고치에 근접했다고 발틱거래소(Baltic Exchange) 자료가 보여줬다. 이란·미국 간 60일 휴전이 이날 종료됐고 호르무즈 통제권을 둘러싼 대립이 이어지는 가운데, 수출국들이 아시아 구매자에게 약속한 원유를 실어나를 선박을 급히 찾으면서 운임이 급등했다. 시노코르(Sinokor)가 운영하는 몽골리아 프로스퍼리티(Mongolia Prosperity)는 8월 21일 선적 예정으로 고율 전쟁위험보험이 부과된다.", "eSum": "VLCC earnings on the Middle East-to-China route neared $510,000/day on 18 August, the highest since late June per Baltic Exchange data. As the 60-day Iran-US ceasefire expired and disputes over Hormuz control persisted, exporters scrambled for ships to move crude promised to Asian buyers. The Sinokor-operated Mongolia Prosperity was booked to load on 21 August with steep war-risk premiums.", "kImp": "호르무즈 위기 장기화로 VLCC 운임이 사상 최고 수준으로 치솟아 탱커 선주 수익이 급증하는 반면, 원유 물류비와 아시아 정유사 조달비용 부담이 커진다.", "eImp": "A prolonged Hormuz crisis has pushed VLCC earnings to extreme highs, boosting tanker owners' profits while raising crude logistics costs and procurement burdens for Asian refiners.", "url": "https://gcaptain.com/oil-supertanker-earnings-on-mideast-route-near-510000-a-day/"}, {"code": "HOT", "title": "Three Chinese Tankers U-Turn in Hormuz as Risks Remain High", "src": "gCaptain", "date": "2026-08-19", "kSum": "중국 연계 VLCC 3척(시 V·헤스티아·이렉터)이 호르무즈해협에서 위험이 여전히 높은 가운데 진로를 되돌렸다. 트럼프 대통령이 이란에 강경 노선을 취하면서 통항 정상화 전망이 흐려진 데 따른 것이다. 화요일 영국 해군은 오만 연안을 빠져나가던 선박이 정체불명 발사체에 피격됐다고 보고했다. 일부 선박은 트랜스폰더를 끈 채 여전히 해협을 통과하고 있다.", "eSum": "Three China-linked VLCCs (Sea V, Hestia, Erecter) U-turned in the Strait of Hormuz as risks stayed elevated after President Trump took a hard line on Iran, dimming hopes of normalised traffic. The UK Navy reported a vessel struck by an unknown projectile off Oman on Tuesday, while some ships still transit with transponders off.", "kImp": "주요 선박들의 회항은 호르무즈 통항의 극심한 불확실성을 보여주며, 원유 흐름 차질과 운임 변동성, 지정학 리스크 확대를 반영한다.", "eImp": "The U-turns underscore extreme uncertainty over Hormuz transits, reflecting disrupted crude flows, freight volatility and heightened geopolitical risk.", "url": "https://gcaptain.com/three-chinese-tankers-u-turn-in-hormuz-as-risks-remain-high/"}, {"code": "HOT", "title": "Saudi Arabia Resumes Oil Loadings, Sales From Inside Strait of Hormuz", "src": "gCaptain", "date": "2026-08-18", "kSum": "사우디 아람코(Saudi Aramco)가 지난주 호르무즈해협 내부에서 원유 선적을 재개하고 추가 현물 중질원유 화물을 제공하고 있다고 로이터가 전했다. VLCC 3척(말레이시아·알제리·싱가포르 프로스퍼리티)이 8월 12~16일 주아이마·라스타누라 터미널에서 각 200만 배럴을 선적했다. 다만 홍해에서는 후티 봉쇄로 수출이 여전히 제약돼 이집트 시디케이르 항으로 우회 물량을 제공하고 있다.", "eSum": "Saudi Aramco resumed crude loadings from inside the Strait of Hormuz last week and is offering additional spot heavy grades, Reuters reported. Three VLCCs (Malaysia, Algeria and Singapore Prosperity) each loaded 2m barrels at Juaymah and Ras Tanura on 12-16 August. Exports via the Red Sea remain constrained by the Houthi blockade, with cargoes offered via Egypt's Sidi Kerir instead.", "kImp": "세계 최대 수출국의 선적 재개는 타이트한 중질유 공급 완화에 기여하지만, 호르무즈·홍해 이중 봉쇄로 사우디 수출은 여전히 위축돼 있다.", "eImp": "The top exporter's resumption eases tight heavy-grade supply, but Saudi exports remain curbed by the dual Hormuz and Red Sea chokepoints.", "url": "https://gcaptain.com/saudi-arabia-resumes-oil-loadings-sales-from-inside-strait-of-hormuz/"}, {"code": "HOT", "title": "Trump Takes Iran Hard Line as Hormuz Tensions Set New Normal", "src": "gCaptain", "date": "2026-08-19", "kSum": "트럼프 대통령이 화요일 이란과의 협상이 진행 중이지 않다고 밝히면서 호르무즈해협 통제권을 둘러싼 중동 갈등이 교착 상태에 빠졌다. 이란 측 협상대표는 미국이 해상 봉쇄 해제, 석유 제재 철회, 군사작전 중단 등 요구 목록을 수용할 때까지 해협을 재개방하지 않겠다고 밝혔다. 강경 대치가 이어지며 '새로운 정상 상태'가 굳어지고 있다.", "eSum": "President Trump said on Tuesday there were no ongoing talks with Iran, leaving the Middle East conflict and control of the Strait of Hormuz in limbo. Iran's negotiator said Hormuz would not reopen until Washington accepts demands including lifting the naval blockade, removing oil sanctions and ending military operations, entrenching a hard-line standoff as the 'new normal.'", "kImp": "미·이란 외교 교착은 호르무즈 위기의 조기 해소 가능성을 차단해 원유 시장과 탱커 시황의 고변동성 장기화를 예고한다.", "eImp": "The US-Iran diplomatic deadlock removes any near-term path to resolving the Hormuz crisis, pointing to prolonged high volatility in oil and tanker markets.", "url": "https://gcaptain.com/trump-takes-iran-hard-line-as-hormuz-tensions-set-new-normal/"}, {"code": "HOT", "title": "Seafarer Killed in Latest Strait of Hormuz Attack on Commercial Shipping", "src": "gCaptain", "date": "2026-08-18", "kSum": "호르무즈해협을 통항하던 벌크선 2척이 각각 발사체에 피격돼 선원 2명의 사상자가 발생했으며, 라이베리아 선적 미노안 디그니티(Minoan Dignity)에서 선원 1명이 사망했다. 상선에 대한 공격이 이어지며 통항 선박과 선원의 안전 위협이 현실화되고 있다.", "eSum": "Two bulk carriers were struck by projectiles in separate attacks while transiting the Strait of Hormuz, causing two crew casualties, including one seafarer killed aboard the Liberia-flagged Minoan Dignity. The continuing attacks are turning threats to transiting ships and crews into deadly reality.", "kImp": "선원 사망 사고는 호르무즈 통항의 인명 위험을 부각시켜 선원 확보·용선 기피를 심화시키고, 통항 기피와 운임 상승을 가속한다.", "eImp": "A fatality highlights the human risk of Hormuz transits, deepening reluctance among crews and charterers and accelerating avoidance and higher freight.", "url": "https://gcaptain.com/seafarer-killed-in-latest-strait-of-hormuz-attack-on-commercial-shipping/"}, {"code": "HOT", "title": "Opinion: Oil Market Starts Pricing in a Prolonged Hormuz Crisis", "src": "gCaptain", "date": "2026-08-18", "kSum": "석유 시장이 중동 에너지 공급 차질을 일시적 충격이 아닌 새로운 현실로 받아들이기 시작했다는 분석이다. 호르무즈 위기가 단기간에 해소되지 않을 것이라는 전망이 확산되며, 시장은 지속적 공급 위험을 가격에 반영하기 시작했다. 이는 유가 프리미엄과 물류 리스크의 구조적 재평가를 의미한다.", "eSum": "The oil market is increasingly treating Middle East supply disruption not as a temporary shock but as a new reality, an opinion piece argues. As expectations spread that the Hormuz crisis will not resolve quickly, markets are beginning to price in persistent supply risk, implying a structural re-rating of oil premiums and logistics risk.", "kImp": "위기의 장기화를 반영한 시장 심리 전환은 유가·운임의 고착화를 시사하며, 해운·에너지 업계의 리스크 관리 전략 재편을 촉발한다.", "eImp": "A shift to pricing in a prolonged crisis signals entrenched oil and freight premiums, prompting shipping and energy players to rework risk-management strategies.", "url": "https://gcaptain.com/opinion-oil-market-starts-pricing-in-a-prolonged-hormuz-crisis/"}, {"code": "HOT", "title": "Covert Mideast Oil Flows Are Keeping Global Prices In Check", "src": "gCaptain", "date": "2026-08-16", "kSum": "중동 산유국들이 호르무즈를 우회해 대규모 원유를 은밀히 실어나르며 세계 유가 급등을 억제하고 있다고 블룸버그가 전했다. 페르시아만 생산국들이 STS(선박간 이송)와 우회 물류를 통해 아시아 구매자에게 원유를 지속 공급하면서, 위기 속에서도 물량 흐름이 유지되고 있다. 다만 이러한 '그림자 물류'는 추적이 어렵고 리스크가 높다.", "eSum": "Middle Eastern producers are covertly shuttling large volumes of crude out of the Persian Gulf, keeping global prices in check, Bloomberg reported. Gulf producers keep supplying Asian buyers via ship-to-ship transfers and workaround logistics, sustaining flows despite the crisis, though such shadowy movements are hard to track and carry elevated risk.", "kImp": "우회·은밀 물류가 공급을 지탱해 유가 급등을 막고 있으나, 추적 곤란·안전 위험이 커 위기 심화 시 시장 충격 가능성이 상존한다.", "eImp": "Covert workaround flows are cushioning prices, but their opacity and safety risks mean the market remains vulnerable to shocks if the crisis deepens.", "url": "https://gcaptain.com/covert-mideast-oil-flows-are-keeping-global-prices-in-check/"}, {"code": "HOT", "title": "Trump Rejects Iran Truce Extension as Oil Tops $90", "src": "gCaptain", "date": "2026-08-17", "kSum": "트럼프 대통령이 이란과의 만료 예정 합의 연장에 관심이 없다고 밝히면서 중동 평화 전망이 다시 후퇴했고, 유가는 배럴당 90달러를 돌파했다. 레바논에서 교전이 재발하는 등 긴장이 고조되며, 60일 휴전 종료를 앞두고 호르무즈 위기가 재격화될 우려가 커졌다.", "eSum": "President Trump said he is not interested in extending the expiring agreement with Iran, dealing a fresh setback to Middle East peace prospects as oil topped $90 a barrel. With fighting flaring anew in Lebanon and the 60-day ceasefire ending, fears grew of a renewed escalation of the Hormuz crisis.", "kImp": "휴전 연장 거부와 유가 90달러 돌파는 위기 재격화 신호로, 원유 공급 차질과 운임·보험료 급등 우려를 다시 키운다.", "eImp": "Rejecting the truce extension as oil breaks $90 signals renewed escalation, reviving fears of crude supply disruption and surging freight and insurance costs.", "url": "https://gcaptain.com/trump-rejects-iran-truce-extension-as-oil-tops-90/"}, {"code": "HOT", "title": "Strait of Hormuz Brief: 19 August 2026", "src": "Lloyd's List Intelligence", "date": "2026-08-19", "kSum": "로이드리스트 인텔리전스의 8월 19일자 호르무즈 브리핑은 미·이란 외교가 사실상 붕괴돼 단기 긴장 완화 경로가 사라졌다고 평가했다. 선주·운항사들은 테헤란과 워싱턴의 엇갈린 메시지 속에 여전히 통항을 꺼리고 있으며, 화물은 푸자이라·코르파칸·오만·제다 육상연결로로 우회되고 있다. VLCC·수에즈막스 현물 운임은 호르무즈 노출 항로를 중심으로 강세를 이어가고 있다.", "eSum": "Lloyd's List Intelligence's 19 August Hormuz brief assessed that US-Iran diplomacy has effectively collapsed, removing any near-term de-escalation path. Owners and operators remain reluctant to transit amid mixed signals from Tehran and Washington, with cargo rerouted via Fujairah, Khor Fakkan, Oman and the Jeddah land bridge, while VLCC and suezmax spot rates stay strong on Hormuz-exposed trades.", "kImp": "권위 있는 정보기관의 브리핑은 위기의 구조적 장기화와 물류 우회 고착을 확인시켜, 중동 원유 물류와 탱커 시황의 지속적 압박을 예고한다.", "eImp": "The authoritative brief confirms structural persistence of the crisis and entrenched rerouting, signalling sustained pressure on Middle East crude logistics and tanker markets.", "url": "https://www.lloydslistintelligence.com/resources/blog/strait-of-hormuz-brief-19-august-2026"}]}, {"code": "SYS", "type": "news", "kTitle": "Section 20. 시스템·앱", "eTitle": "Section 20. System & App", "items": [{"code": "SYS", "title": "NorthStandard joins SSI to bring human risk into maritime management decisions", "src": "The Digital Ship", "date": "2026-08-19", "kSum": "노스스탠다드(NorthStandard)가 지속가능해운이니셔티브(SSI)에 가입하며 해상보험사로서 SSI의 인적위험·회복력(Human Risk & Resilience) 플랫폼에 참여해 인적 리스크를 관리 의사결정에 반영한다.", "eSum": "NorthStandard joined the Sustainable Shipping Initiative (SSI), bringing a marine insurer into the organisation's Human Risk & Resilience platform to factor human risk into management decisions.", "kImp": "보험사의 인적위험 플랫폼 참여는 선박관리 의사결정에 인적 요소 데이터를 통합하는 흐름을 강화한다.", "eImp": "An insurer joining a human-risk platform reinforces the trend of embedding human-factors data into ship management decision-making.", "url": "https://thedigitalship.com/news/maritime-software/northstandard-joins-ssi-to-bring-human-risk-into-maritime-management-decisions/"}, {"code": "SYS", "title": "JNPA appoints ATAI for AI-enabled digital twin project", "src": "Smart Maritime Network", "date": "2026-08-18", "kSum": "인도 자와할랄네루항만청(JNPA)이 AI/ML 기반 디지털 트윈 프로젝트의 자문사로 ATAI를 선임했다.", "eSum": "India's Jawaharlal Nehru Port Authority (JNPA) appointed ATAI as an advisor for its AI/ML-enabled digital twin project.", "kImp": "AI 디지털 트윈 도입은 항만 운영의 예측·최적화 역량을 강화한다.", "eImp": "An AI digital twin strengthens predictive and optimisation capabilities in port operations.", "url": "https://smartmaritimenetwork.com/2026/08/18/jnpa-appoints-atai-for-ai-enabled-digital-twin-project/"}, {"code": "SYS", "title": "WaveBL and Coneksion strengthen custom data workflows", "src": "Smart Maritime Network", "date": "2026-08-18", "kSum": "웨이브BL(WaveBL)과 코넥션(Coneksion)이 기술 협력을 확대해 해상 부킹 데이터와 무역 문서 워크플로를 연결한다.", "eSum": "WaveBL and Coneksion announced an expansion of their technology collaboration to connect ocean booking data with trade document workflows.", "kImp": "부킹 데이터와 전자 무역문서의 연계는 서류 처리 자동화와 공급망 가시성을 높인다.", "eImp": "Linking booking data with electronic trade documents advances paperwork automation and supply-chain visibility.", "url": "https://smartmaritimenetwork.com/2026/08/18/wavebl-and-coneksion-strengthen-custom-data-workflows/"}]}, {"code": "SMGR", "type": "news", "kTitle": "Section 21. 선박관리사", "eTitle": "Section 21. Ship Managers", "items": [{"code": "SMGR", "title": "A new home for our London team", "src": "Anglo-Eastern", "date": "2026-08-19", "kSum": "앵글로-이스턴(Anglo-Eastern)이 런던 사무소를 슈가하우스아일랜드 Colour Works의 운하변 4,900 sq ft 신규 공간으로 이전했다. 직원 웰빙을 중심으로 설계됐으며 싱가포르·마닐라에 이은 그룹 글로벌 워크플레이스 혁신의 일환이다.", "eSum": "Anglo-Eastern relocated its London office to a new 4,900 sq ft canal-side space at Colour Works, Sugar House Island, designed around employee well-being, as part of the group's global workplace transformation programme following moves in Singapore and Manila.", "kImp": "런던 거점 업그레이드는 앵글로-이스턴의 유럽 고객 대응 역량과 현대적 협업 공간에 대한 지속 투자를 보여준다.", "eImp": "The upgraded London base signals Anglo-Eastern's continued investment in its European client-facing presence and modern workspaces.", "url": "https://www.angloeastern.com/news-and-insights/a-new-home-for-our-london-team/"}, {"code": "SMGR", "title": "Guardians of the ocean: From policy to practice in environmental compliance (LeaderShip Issue 43)", "src": "Anglo-Eastern", "date": "2026-08-20", "kSum": "앵글로-이스턴(Anglo-Eastern)이 환경 규정 준수의 정책-실무 연계를 주제로 한 사보 'LeaderShip' 2026년 9월호(Issue 43)를 발간했다. 선박관리 최신 동향과 사례를 다룬다.", "eSum": "Anglo-Eastern published the September 2026 (Issue 43) edition of its LeaderShip publication, focused on translating environmental policy into onboard practice across its managed fleet.", "kImp": "정기 사고(思考) 리더십 시리즈는 규제 강화 속 선주를 안내하는 지식 리더로서의 위상을 강화한다.", "eImp": "The regular thought-leadership series reinforces Anglo-Eastern's positioning as a knowledge leader guiding owners through tightening environmental regulation.", "url": "https://www.angloeastern.com/news-and-insights/guardians-of-the-ocean-from-policy-to-practice-in-environmental-compliance-issue-43/"}, {"code": "SMGR", "title": "Cultivating talent ashore: Internship programme at Hellas Office", "src": "Anglo-Eastern", "date": "2026-08-18", "kSum": "앵글로-이스턴(Anglo-Eastern) 그리스(Hellas) 사무소가 7월 연례 인턴십 프로그램의 새 기수를 맞아 에게대학교(University of the Aegean) 등 4개 대학 학생을 받았다.", "eSum": "Anglo-Eastern's Hellas (Greece) office welcomed the latest intake of its annual Internship Programme, bringing together students from four universities including the University of the Aegean and Alba Graduate Business School.", "kImp": "육상 인재에 대한 조기 투자는 주요 시장인 그리스 해운 허브에 대한 장기적 헌신을 심화한다.", "eImp": "Investing in early-career shore-based talent deepens Anglo-Eastern's long-term commitment to the Greek shipping hub.", "url": "https://www.angloeastern.com/news-and-insights/cultivating-talent-ashore-internship-programme-at-hellas-office/"}, {"code": "SMGR", "title": "Building tomorrow's shore-based leaders: Graduate Trainee Programme in India", "src": "Anglo-Eastern", "date": "2026-08-14", "kSum": "앵글로-이스턴(Anglo-Eastern)이 7월 인도에서 대졸 신입 트레이니 프로그램(Graduate Trainee Programme·GTP) 첫 기수를 선발해 미래 육상 리더 양성의 이정표를 세웠다.", "eSum": "Anglo-Eastern welcomed the inaugural cohort of its Graduate Trainee Programme (GTP) in India, a milestone in its effort to build future shore-based leaders through a structured development programme.", "kImp": "전담 대졸 리더십 파이프라인 구축은 선대 성장을 뒷받침할 육상 관리 인재 확보에 기여한다.", "eImp": "Launching a dedicated graduate leadership pipeline helps secure the shore-side management talent needed to sustain fleet growth.", "url": "https://www.angloeastern.com/news-and-insights/building-tomorrows-shore-based-leaders-graduate-trainee-programme-in-india/"}, {"code": "SMGR", "title": "ICS examines pathways from ratings to future officers, featuring Synergy's crewing COO", "src": "ICS / Synergy Marine Group", "date": "2026-08-20", "kSum": "국제해운회의소(ICS) 리더십 인사이트 기사가 BIMCO/ICS 선원인력보고서 2026를 바탕으로 경력 있는 부원(ratings)의 사관 전환 경로를 조명하며, 시너지마린그룹(Synergy Marine Group) 크루잉 COO 마니시 프라단(Maneesh Pradhan)의 발언과 시너지의 Skill Map·역량보증·시뮬레이션 훈련을 소개했다.", "eSum": "An ICS Leadership Insights article, drawing on the BIMCO/ICS Seafarer Workforce Report 2026, explores addressing the officer shortage through structured career pathways for ratings, featuring Synergy Marine Group's crewing COO Maneesh Pradhan and Synergy's Skill Map, competency assurance and simulation-based training.", "kImp": "사관 부족 해소를 위한 구조적 경력 경로에서 시너지의 선원 역량개발 접근이 모범 사례로 부각된다.", "eImp": "Synergy's seafarer competency-development approach is highlighted as a model for tackling the global officer shortage through structured career pathways.", "url": "https://www.ics-shipping.org/news-item/why-shippings-next-39100-officers-are-already-onboard/"}]}]};